# UTILITY FUNCTIONS (From Skuld 1.5 - UNCHANGED)
# ============================================================================

def parse_value_with_error(value_string):
    """
    Parse CIF value strings that may contain errors in parentheses.
    Example: "1.2345(67)" -> 1.2345, 0.0067
    """
    if not value_string or value_string == '.' or value_string == '?':
        return None, None

    # v2.0.2: the mantissa was \d+\.?\d*, which requires a digit BEFORE the
    # decimal point. CIFs are written both ways, so a value with a leading dot
    # AND a standard uncertainty fell through to the float() fallback, which
    # cannot parse the parentheses either, and the function returned
    # (None, None) -- silently, so the caller sees a missing value rather than
    # a parse failure and the bond simply leaves the analysis.
    #
    #     2.0947(3)   parsed before and now
    #     1.          float fallback, fine before and now
    #     .4890       float fallback, fine before and now
    #     .4890(12)   LOST before, parsed now
    #     -.0181(3)   LOST before, parsed now
    #
    # The same fault in a different place cost ICSD 420711 its shift test: a
    # coordinate written '1.' was rejected by an equivalent pattern in CELL
    # 13b. Worth checking any pattern that reads a number out of a CIF.
    match = re.match(
        r'^([+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?)\((\d+)\)$',
        value_string.strip())
    if match:
        value_str, error_str = match.groups()
        value = float(value_str)

        if '.' in value_str:
            decimal_places = len(value_str.split('.')[1].split('e')[0].split('E')[0])
        else:
            decimal_places = 0

        error = float(error_str) * (10 ** (-decimal_places))
        return value, error
    else:
        try:
            value = float(value_string.strip())
            return value, None
        except ValueError:
            return None, None

def validate_element_combination(cation, anion):
    """Check if cation-anion combination is chemically reasonable"""
    cation_category = db_manager.get_element_category(cation)
    anion_category = db_manager.get_element_category(anion)

    if cation_category == "other" and anion_category == "other":
        return False

    return True

# ============================================================================
# BOND DISTANCE CALCULATION FOR ICSD CIF FILES
# ============================================================================

# A numeric CIF value is not supposed to be quoted, but the ICSD exporter
# quotes any field carrying trailing whitespace, e.g. ICSD 22964 (GdFeO3),
# whose Gd y coordinate is written '0.06269'. gemmi does not raise on this:
# it returns NaN, the site keeps its label and loses its position, and every
# distance to it compares False against both the minimum and the maximum bond
# cut-off. Gd emerged with CN 0, no bond valence sum, confidence HIGH, and the
# structure took the lowest GII in the 934-entry perovskite dataset, computed
# over its iron alone.
_QUOTED_NUMBER = re.compile(
    r"""(?<![\w.])(['"])\s*([+-]?(?:\d+\.?\d*|\.\d+)(?:\(\d+\))?)\s*\1(?![\w.])""")


def _unquote_atom_site_numbers(content):
    """
    Strip quotes from numeric values inside the atom_site loop.

    Confined to that loop, and to data rows within it, so a genuinely quoted
    label such as 'Gd1' and a quoted value elsewhere in the file are both left
    alone. Standard uncertainties are preserved: '0.4655(3) ' becomes
    0.4655(3), which gemmi reads as it always did.

    Returns (content, n_lines_repaired).
    """
    out, n, in_loop = [], 0, False
    for line in content.split('\n'):
        s = line.strip()
        if s.startswith('_atom_site_'):
            in_loop = True
        elif in_loop and (s.startswith('loop_') or s.startswith('data_')
                          or s.startswith(';')
                          or (s.startswith('_') and not s.startswith('_atom_site_'))):
            in_loop = False
        if in_loop and s and s[0] not in '_#;' and not s.startswith('loop_'):
            new = _QUOTED_NUMBER.sub(r'\2', line)
            if new != line:
                n += 1
                line = new
        out.append(line)
    return '\n'.join(out), n

def assert_finite_sites(small_struct, cif_file_path=''):
    """
    Refuse a parsed structure whose coordinates are not all finite.

    gemmi returns NaN rather than raising when an _atom_site_fract_* value
    cannot be converted, so a site survives parsing with a label and no
    position. This is the only place that catches it: NaN passes every
    downstream comparison silently, and the site is not so much rejected as
    never considered.

    Returns (ok, message). The caller decides what to do; this only refuses to
    let it through unremarked.
    """
    bad = []
    for s in small_struct.sites:
        f = s.fract
        for axis, v in (('x', f.x), ('y', f.y), ('z', f.z)):
            if not math.isfinite(v):
                bad.append(f'{s.label}.{axis}')
    if not bad:
        return True, ''
    return False, ('non-finite fractional coordinates on ' + ', '.join(bad)
                   + '; the CIF parsed but the positions did not')

# ICSD exports occasionally carry a non-breaking space that has been encoded
# twice, U+00C2 followed by U+00A0, in a citation author name. CIF 1.1 permits
# only ASCII 32-126 in an unquoted value, so gemmi refuses the whole file and
# the structure is lost with the message 'Failed to parse CIF file', which
# points nowhere near the actual line. Four perovskites in the ICSD set fail
# this way; one of them, ICSD 124972, on a single character.
_MANGLED_NBSP = '\u00c2\u00a0'
_INVISIBLE = '\u00a0\u2007\u202f\u200b\u200c\u200d\ufeff'


def normalise_cif_to_ascii(content):
    """
    Bring a CIF within the CIF 1.1 character set without changing its tokens.

    Invisible characters are DELETED rather than replaced with a space. That
    distinction is the whole point: 'Akamatsu,<NBSP>Hirofumi' is one token, and
    substituting a space would split it in two, turning a character error into
    a loop row-length error in an unquoted field. Deleting gives
    'Akamatsu,Hirofumi', which is one token and still legible.

    Everything else above 127 is folded to its ASCII base where one exists and
    dropped where none does, so accented author names survive readably.

    Returns (content, n_characters_repaired).
    """
    import unicodedata

    n = 0
    if _MANGLED_NBSP in content:
        n += content.count(_MANGLED_NBSP)
        content = content.replace(_MANGLED_NBSP, '')
    for ch in _INVISIBLE:
        if ch in content:
            n += content.count(ch)
            content = content.replace(ch, '')
    if not content.isascii():
        out = []
        for ch in content:
            if ord(ch) < 128:
                out.append(ch)
                continue
            n += 1
            out.append(''.join(c for c in unicodedata.normalize('NFKD', ch)
                               if ord(c) < 128 and not unicodedata.combining(c)))
        content = ''.join(out)
    return content, n

def clean_cif_for_gemmi(cif_file_path):
    """
    Pre-process CIF file to remove lines that cause gemmi parsing errors.

    Removes _chemical_name_structure_type which often has UTF-8 encoding issues in ICSD files.
    Replaces non-standard reverse rhombohedral symops ('HR' suffix) with standard obverse
    centering, which gemmi requires for space group determination.

    v2.0.3: also unquotes numeric values inside the atom_site loop. A quoted
    number is not legal in that position and gemmi returns NaN rather than
    raising, so the site keeps its label and loses its position. See
    _unquote_atom_site_numbers.

    Returns cleaned CIF as string for gemmi to parse.
    """
    try:
        import re

        # Read file with UTF-8 encoding, replacing errors
        with open(cif_file_path, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()

        content = ''.join(lines)

        # v2.0.3 (rule 0). Both repairs must run before anything else looks at
        # the file, and before gemmi sees it at all. ASCII first, because it is
        # about bytes; unquoting second, because it is about tokens.
        content, _n_ascii = normalise_cif_to_ascii(content)
        content, _n_unquoted = _unquote_atom_site_numbers(content)
        # v2.0.46: one reading of every atom's symbol (normalise_atom_types)
        content, _type_notes = normalise_atom_types(content)

        # v1.8.3 (B13): the two repairs below are load-bearing, not cosmetic.
        # Without the _chemical_name_structure_type strip, 22 of the 142
        # structures in the reference set do not parse at all, including most
        # of the NaCrO2 entries; without the HR rewrite several reverse-
        # rhombohedral space groups fail to resolve. Both log when they fire so
        # a change in parsing behaviour is visible in the run output.
        _repairs = []

        if _n_ascii:
            _repairs.append(f'normalised {_n_ascii} non-ASCII character'
                            f'{"s" if _n_ascii > 1 else ""}')
        if _n_unquoted:
            _repairs.append(f'unquoted {_n_unquoted} atom_site numeric value'
                            f'{"s" if _n_unquoted > 1 else ""}')
        _repairs.extend(_type_notes)

        # Fix non-standard reverse rhombohedral centering ('HR' suffix)
        # Some older ICSD CIFs encode symops in the reverse setting, which gemmi
        # cannot match to a tabulated space group. Replace the HM label and
        # regenerate symops from the IT number using standard obverse centering.
        if ' HR' in content:
            sg_tags = ['_space_group_name_H-M_alt', '_symmetry_space_group_name_H-M']
            has_hr = any(tag in content and ' HR' in content for tag in sg_tags)

            if has_hr:
                try:
                    import gemmi as _gemmi

                    # Fix HM label
                    _repairs.append('HR->H symmetry setting')
                    content = content.replace(" HR'", " H'")
                    content = content.replace(' HR\r', ' H\r')
                    content = content.replace(' HR\n', ' H\n')

                    # Get IT number and regenerate standard symops
                    it_match = re.search(r'_space_group_IT_number\s+(\d+)', content)
                    if not it_match:
                        it_match = re.search(r'_symmetry_Int_Tables_number\s+(\d+)', content)

                    if it_match:
                        sg = _gemmi.find_spacegroup_by_number(int(it_match.group(1)))
                        if sg:
                            ops = sg.operations()
                            new_loop = 'loop_\n_space_group_symop_id\n_space_group_symop_operation_xyz\n'
                            for i, op in enumerate(ops):
                                new_loop += f"{i+1} '{op.triplet()}'\n"

                            # Replace old symops loop
                            pattern = r"loop_\s*\n_space_group_symop_id\s*\n_space_group_symop_operation_xyz\s*\n((?:\d+\s+'[^']+'\s*[\r\n]+)+)"
                            content = re.sub(pattern, new_loop, content)
                            print(f"  Note: Replaced reverse rhombohedral symops with standard obverse (SG {sg.hm})")
                except Exception as e:
                    print(f"  Warning: Could not fix HR symops: {e}")

        # Re-split into lines for structure_type removal
        lines = content.split('\n')

        cleaned_lines = []
        i = 0
        while i < len(lines):
            line = lines[i]

            # Check if this line contains the problematic tag
            if '_chemical_name_structure_type' in line:
                if 'structure_type strip' not in _repairs:
                    _repairs.append('structure_type strip')
                # Skip this line
                # Also skip the next line if it doesn't start with _ or # (it's the value)
                i += 1
                if i < len(lines):
                    next_line = lines[i].strip()
                    # If next line is a value (not a tag), skip it too
                    if next_line and not next_line.startswith('_') and not next_line.startswith('#') and not next_line.startswith('loop_') and not next_line.startswith('data_'):
                        i += 1
                continue

            cleaned_lines.append(line)
            i += 1

        cleaned = '\n'.join(cleaned_lines)
        if _repairs:
            _dbg(f"    [CIF repair] {', '.join(_repairs)} (B13)")
        return cleaned

    except (NameError, AttributeError, TypeError, SyntaxError, IndexError):
        # v2.0.3: these are defects in this function, not in the CIF. Swallowed,
        # they surface as 'Could not read CIF file' on every structure in the
        # run and send the reader to look at their data for a fault that is in
        # the code. Let them out.
        raise
    except Exception as e:
        print(f"  Warning: Error cleaning CIF file "
              f"({type(e).__name__}: {e}): {cif_file_path}")
        return None


def formula_from_cif(cif_path):
    """
    _chemical_formula_sum, read from the CLEANED text.

    v2.0.13. Two faults sat here. The formula was read with PyCifRW straight
    off the RAW file, while every other read in Eir goes through
    clean_cif_for_gemmi - so a file the repairs fix parsed for gemmi and
    raised here. ICSD 118400 and its three siblings carry a double-encoded
    non-breaking space in an author name and are exactly that case.

    And the exception list did not include PyCifRW's own StarError, so one
    unparseable file ended a whole batch rather than being recorded and
    skipped.

    A regex on the cleaned text is used first: this is one tag, and building
    a full STAR parse tree to read it is both slower and more fragile than
    the string it came from.
    """
    try:
        text = clean_cif_for_gemmi(cif_path)
    except Exception as _e:
        _note_read_failure(cif_path, 'formula/clean', _e)
        text = None

    if text:
        m = re.search(r"_chemical_formula_sum\s+(?:'([^']*)'|\"([^\"]*)\""
                      r"|;\s*\n(.*?)\n;|(\S.*))", text)
        if m:
            val = next((g for g in m.groups() if g), '')
            return ' '.join(val.split())

    # Fall back to the parser, on the cleaned text where there is one.
    tmp_path = None
    try:
        if text:
            with tempfile.NamedTemporaryFile(mode='w', suffix='.cif',
                                             delete=False,
                                             encoding='utf-8') as tmp:
                tmp.write(text)
                tmp_path = tmp.name
        cf = ReadCif(tmp_path or str(cif_path))
        return cf[list(cf.keys())[0]].get('_chemical_formula_sum', '')
    except Exception as _e:
        # Deliberately broad. PyCifRW raises StarError, which belongs to no
        # standard hierarchy, and a formula that cannot be read must not end
        # the batch: the file is recorded and analysis continues without it.
        _note_read_failure(cif_path, 'formula', _e)
        return ''
    finally:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass


# v2.0.44: AN ANION POSITION HELD BY MORE THAN ONE SITE LABEL.
#
# The neighbour list in calculate_bonds_from_positions is deduplicated by
# POSITION: images closer than 0.05 A are one atom. That is right for the
# images of one site and wrong for two species sharing a position - O/F in an
# oxyfluoride, O/N in an oxynitride, O/S, O/OH. The second species was
# discarded, and which one survived depended on the order of the CIF:
# synthetic PrOF (O and F half each on 8c) gave Pr 1.573 v.u. with O listed
# first and 1.243 with F first, against about 2.8 either way. Every cation
# bonded to a shared anion position was summed over half its ligands, and
# the result was usually ACCEPT, because nothing else was wrong.
#
# The anion-centred engine (CELL 3) learned this in v2.0.2 for cations on
# shared positions and deduplicates per label. The cation side cannot simply
# do the same: a second label at one point would count as a second bond, and
# CN, the shell rules and the geometry would all see 16 ligands around an
# eight-coordinate cation.
#
# So the position stays ONE ligand, carried by its first-listed label, and
# the other species are recorded here and added to the sum with their own
# occupancy, R0 and b (perform_calculations_and_report). CN, shell and
# geometry count positions; the sum counts species. Measured on the ICSD
# fluorite and pyrochlore sets (1988 entries): 25 share an anion position
# between two elements (O/F, O/N, O/S), every one at identical coordinates.
#
# NOT covered: one label split over its own symmetry images closer than
# 0.05 A. Those cannot be told from images that coincide only to the
# precision of the deposited coordinates (three decimals is 0.01 A on a 10 A
# cell), so the dedup still treats them as one atom. None occurs in those
# 1988 entries.
COLOCATED_TOL = 0.05          # A, the neighbour dedup's own tolerance
COLOCATED_IMAGE_TOL = 0.02    # A, images closer than this are one atom, as
                              # ANION_DEDUP_TOL in CELL 3
_EIR_COLOCATED = {}           # carrying label -> [(label, element, n), ...]
# v2.0.46: pairs closer than CATION_ANION_ABSOLUTE_MIN that the model fills
# one at a time, set aside by the bond finder: [(label, label, distance)]
_EIR_ALTERNATIVES = []


def _alternatives_summary():
    """The pairs the bond finder set aside as alternatives, shortest
    first, for the alternative_contacts_set_aside column; None if none."""
    if not _EIR_ALTERNATIVES:
        return None
    best = {}
    for a, b, d in _EIR_ALTERNATIVES:
        k = tuple(sorted((a, b)))
        best[k] = min(d, best.get(k, d))
    items = sorted(best.items(), key=lambda kv: kv[1])
    out = '; '.join(f'{a}-{b} {d:.3f} A' for (a, b), d in items[:6])
    return out + (f' (+{len(items) - 6} more)' if len(items) > 6 else '')


def calculate_bonds_from_positions(cif_file_path, max_bond_distance=4.2):
    """
    Calculate bond distances from CIF using proper crystallographic symmetry operations.

    Uses gemmi library for robust handling of:
    - Partial occupancy (e.g., Na site 2/3 occupied)
    - Mixed occupancy (e.g., Cr0.8Ti0.2 on same site)
    - All space groups (R-3m, P63/mmc, C2/m, etc.)
    - Proper symmetry code generation

    CRITICAL: ICSD files are small molecule/inorganic structures, not macromolecular.
    Uses SmallStructure, not Structure.

    Args:
        cif_file_path: Path to CIF file
        max_bond_distance: Maximum bond distance to consider (Ångströms).
            v1.8.1: raised 3.5 -> 4.2. At 3.5 the true coordination-shell
            boundary in layered oxides often fell outside the candidate
            list, so the gap cut fired on intra-shell distortion instead
            and returned CN 2/3/4 for octahedral sites.

    Returns:
        dict with bond data formatted like GSAS-II _geom_bond output, or None if failed

    v2.0.3: refuses a structure whose parsed coordinates are not all finite,
    and rejects a non-finite distance explicitly rather than by accident.
    gemmi returns NaN, not an error, when an _atom_site_fract_* value cannot be
    converted, and the old candidate filter tested `distance < 0.01 or distance
    > max_bond_distance`, both of which are False for NaN. A site with no
    position therefore acquired no bonds, reached CN 0, produced no bond
    valence sum, and was reported with confidence HIGH. ICSD 22964 (GdFeO3)
    took the lowest GII in the 934-entry perovskite dataset that way, computed
    over its iron alone, because the Gd y coordinate is deposited as the quoted
    string '0.06269 '.
    """
    try:
        import gemmi
    except ImportError:
        print("  ✗ gemmi not available - install with: pip install gemmi")
        print("    gemmi is required for proper crystallographic bond calculation")
        return None

    import tempfile

    try:
        # Read file with UTF-8 error handling
        cleaned_cif = clean_cif_for_gemmi(cif_file_path)
        if cleaned_cif is None:
            print("  ✗ Could not read CIF file")
            return None

        # Write to temporary file
        with tempfile.NamedTemporaryFile(mode='w', suffix='.cif', delete=False, encoding='utf-8') as tmp:
            tmp.write(cleaned_cif)
            tmp_path = tmp.name

        try:
            # Read CIF document
            doc = gemmi.cif.read(tmp_path)
            block = doc.sole_block()

            # CRITICAL: Use SmallStructure for ICSD (small molecule/inorganic) CIFs
            # NOT Structure (macromolecular)
            small_struct = gemmi.make_small_structure_from_block(block)


        finally:
            # Clean up temp file
            import os
            # v2.0.3: narrowed from a bare except. Failing to delete a temp file
            # is not a reason to swallow a KeyboardInterrupt or a NameError.
            try:
                os.unlink(tmp_path)
            except OSError:
                pass

        # v1.8.6: a CIF may declare its symmetry with only
        # _space_group_IT_number and no H-M name or symop loop. That is legal
        # CIF and several programs emit it, but gemmi leaves .spacegroup as
        # None and the supercell loop below then raises AttributeError, which
        # reaches the user as "No M-X bonds found". Four other functions in
        # this file already recover from this; this one did not.
        if small_struct is not None and small_struct.spacegroup is None:
            _itm = (re.search(r'_space_group_IT_number\s+(\d+)', cleaned_cif) or
                    re.search(r'_symmetry_Int_Tables_number\s+(\d+)', cleaned_cif))
            if _itm:
                _sg = gemmi.find_spacegroup_by_number(int(_itm.group(1)))
                if _sg is not None:
                    small_struct.spacegroup = _sg
                    print(f"  Note: space group taken from IT number "
                          f"{_itm.group(1)} ({_sg.hm})")
        if small_struct is not None and small_struct.spacegroup is None:
            print("  ✗ No usable space group: the CIF gives no symmetry "
                  "operations, no H-M name and no IT number.")
            return None


        if not small_struct or len(small_struct.sites) == 0:
            print("  ✗ No atomic sites found in CIF")
            return None

        # v2.0.3: a site can survive parsing with a label and no position. That
        # is the one failure mode nothing downstream can see, because NaN
        # compares False against every threshold it meets, so the site is never
        # rejected, merely never considered.
        _ok, _why = assert_finite_sites(small_struct, cif_file_path)
        if not _ok:
            print(f"  ✗ {_why}")
            return None

        # Build bond data in GSAS-II format
        bond_data = {
            'bond_label_1': [],
            'bond_label_2': [],
            'bond_distance': [],
            'bond_symmetry_2': []
        }

        bond_count = 0
        atom_type_pairs = set()

        # Debug: Print all sites found
        _dbg(f"  Debug: Found {len(small_struct.sites)} sites in asymmetric unit:")
        _EIR_GEOMETRY.clear()
        for site in small_struct.sites:
            frac = site.fract
            _dbg(f"    {site.label}: {site.element.name} at ({frac.x:.4f}, {frac.y:.4f}, {frac.z:.4f}) occ={site.occ:.2f}")

        # CRITICAL: Generate full supercell for proper coordination detection
        # Gemmi's neighbor search works with asymmetric units, but we need all atoms
        # Generate 3x3x3 supercell to ensure we find all neighbors within cutoff
        _dbg(f"  Generating 3×3×3 supercell for coordination analysis...")

        supercell_atoms = []
        _img_n = image_range(small_struct.cell, max_bond_distance)
        _img_rng = range(-_img_n, _img_n + 1)

        # For each site in asymmetric unit
        for site in small_struct.sites:
            elem_type = site.element.name
            site_label = site.label

            # Apply all symmetry operations
            for op in small_struct.spacegroup.operations():
                # Transform fractional coordinates.
                #
                # v2.0.35: AND WRAP THE IMAGE BACK INTO THE CELL. Without this
                # the shell below stops surrounding a site whose deposited
                # coordinates lie outside [0,1), and neighbours fall off the
                # edge: ICSD 23164 found three of six Os-O bonds at 1.94 A,
                # gave Os CN 3 against a formal 5, and came out ACCEPT because
                # every bond that survived was individually plausible.
                transformed_frac = wrap_into_cell(op.apply_to_xyz(
                    [site.fract.x, site.fract.y, site.fract.z]))

                # Lattice translations, enough of them to cover the cutoff.
                for i in _img_rng:
                    for j in _img_rng:
                        for k in _img_rng:
                            # Add lattice translation
                            final_frac = [
                                transformed_frac[0] + i,
                                transformed_frac[1] + j,
                                transformed_frac[2] + k
                            ]

                            # Convert to Cartesian
                            cart_pos = small_struct.cell.orthogonalize(gemmi.Fractional(*final_frac))

                            supercell_atoms.append({
                                'label': site_label,
                                'element': elem_type,
                                'position': cart_pos,
                                'frac': final_frac,
                                'original_site': site
                            })

        _dbg(f"  Generated {len(supercell_atoms)} atoms in supercell")

        # v2.0.44: which anion labels share a position, and which label
        # carries it. See COLOCATED_TOL above. The first-listed label claims
        # every later one whose images lie within the tolerance of it, with
        # the number of such images (1 at identical coordinates).
        _EIR_COLOCATED.clear()
        _coloc_alias = {}
        # v2.0.46: and any species the CIF types as an anion. H is not in
        # _ANION_SET, so the hydride sharing 8c with oxygen in a fluorite
        # oxyhydride (LnHO) was never recorded and the cation summed O alone
        # at its partial occupancy (Ho 2.14 for a valence of 3). Only a
        # species within COLOCATED_TOL of another anion is affected: H(+) in
        # a hydroxide sits about 0.97 A from its oxygen and is never there.
        # v2.0.46: and less a halogen the CIF states is positive, the central
        # atom of a perchlorate or an iodate (_stated_positive_halogens).
        _pos_hal = _stated_positive_halogens(cif_file_path)
        _an_here = set(_ANION_SET) - _pos_hal
        _coloc_set = (_an_here | _stated_anions(cif_file_path))
        _an_sites = [s for s in small_struct.sites
                     if s.element.name in _coloc_set]
        if len(_an_sites) > 1:
            _an_imgs = {}
            for _a in supercell_atoms:
                if _a['element'] in _coloc_set:
                    _an_imgs.setdefault(_a['label'], []).append(_a['position'])
            for _i, _si in enumerate(_an_sites):
                if _si.label in _coloc_alias:
                    continue
                _pi = site_centre(small_struct.cell, _si)
                for _sj in _an_sites[_i + 1:]:
                    if _sj.label in _coloc_alias or _sj.label == _si.label:
                        continue
                    _pd = PointDedup(COLOCATED_IMAGE_TOL)
                    _n = 0
                    for _p in _an_imgs.get(_sj.label, ()):
                        if (_p.dist(_pi) <= COLOCATED_TOL
                                and not _pd.seen_or_add(_p.x, _p.y, _p.z)):
                            _n += 1
                    if _n:
                        _EIR_COLOCATED.setdefault(_si.label, []).append(
                            (_sj.label, _sj.element.name, _n))
                        _coloc_alias[_sj.label] = (_si.label, _si.element.name)
            if _EIR_COLOCATED:
                _dbg("  Shared anion position(s): " + "; ".join(
                    f"{_c} carries " + ", ".join(_l for _l, _e, _n in _v)
                    for _c, _v in _EIR_COLOCATED.items()))

        # v2.0.46: G1's form of the packing gates' rule. Two positions closer
        # than CATION_ANION_ABSOLUTE_MIN whose occupancies the model can fill
        # one at a time are alternatives, not a bond. Disordered NaNO2, KNO2
        # and KBF4 models put N and O positions 0.46 A apart at occupancies
        # 1/6 and 1/3, and about 25 ICSD entries were expunged on G1 for a
        # contact between two orientations that never coexist. Only below
        # the floor: the real N-O bonds of the same disordered group also join
        # partial positions. Hydrogen is left out: O-H is a bond at 0.97 A
        # whatever the occupancies of a disordered hydroxyl.
        _EIR_ALTERNATIVES.clear()
        _alt_esd = _occupancy_esds(cif_file_path)
        _alt_tot = _position_occupancies(small_struct, _alt_esd)

        # Now find neighbors by simple distance calculation
        for site in small_struct.sites:
            # v2.0.35: wrapped with its images. A site deposited at x = 1.288
            # measured from where the file puts it sits at the edge of its own
            # translation block; wrapping the images alone left four sites of
            # 598 still short at 4.2 A and twenty-six at 5.0 A.
            site_orth = site_centre(small_struct.cell, site)
            elem1 = site.label
            elem1_type = site.element.name

            neighbors_for_site = []

            # Check distance to every atom in supercell
            for atom_dict in supercell_atoms:
                distance = atom_dict['position'].dist(site_orth)

                # Keep only atoms inside the candidate shell. Written as a
                # positive test rather than as two exclusions: for a finite
                # distance the two are identical, and for NaN the exclusions
                # are both False while this is False, so a distance that is not
                # a number is rejected here instead of silently admitted.
                if not (0.01 <= distance <= max_bond_distance):
                    continue
                if (distance < CATION_ANION_ABSOLUTE_MIN
                        and elem1_type not in CATION_FLOOR_EXCLUDED_ELEMENTS
                        and atom_dict['element'] not in CATION_FLOOR_EXCLUDED_ELEMENTS
                        and _are_alternatives(site, atom_dict['original_site'],
                                              _alt_esd, _alt_tot)):
                    _EIR_ALTERNATIVES.append((elem1, atom_dict['label'], distance))
                    continue

                neighbors_for_site.append({
                    'label': atom_dict['label'],
                    'element': atom_dict['element'],
                    'position': atom_dict['position'],
                    'distance': distance
                })

            # Deduplicate by position with 0.05Å tolerance
            # Looser tolerance handles general positions in R-3m better
            # v1.8.9: dedup by true separation, not by snapped coordinate.
            # Grid snapping is not a tolerance: two images of the same atom
            # straddling a 0.05 A grid line got different keys and both
            # survived, inflating CN by an exact integer factor.
            # v2.0.26: the same test, in O(1) instead of O(n) per candidate.
            # This scan was 374,727 generator calls over twenty spinels and
            # the largest single line in the profile. See PointDedup in
            # CELL 1b for why searching 27 buckets is exact and grid
            # snapping was not. The comparison below is unchanged, including
            # the <=: it is performed on the same floats in the same order,
            # against fewer candidates.
            DEDUP_TOL = 0.05
            unique_neighbors = []
            _seen_pos = PointDedup(DEDUP_TOL)
            for neighbor in sorted(neighbors_for_site, key=lambda n: n['distance']):
                p = neighbor['position']
                if _seen_pos.seen_or_add(p.x, p.y, p.z):
                    continue
                # v2.0.44: a shared anion position is carried by its
                # first-listed label whichever image the sort kept, so the
                # bond type and the sum do not depend on a floating-point tie.
                _alias = _coloc_alias.get(neighbor['label'])
                if _alias is not None:
                    neighbor = dict(neighbor, label=_alias[0], element=_alias[1])
                unique_neighbors.append(neighbor)

            _dbg(f"  Debug: Site {site.label} ({site.element.name}) has {len(unique_neighbors)} neighbors in supercell")
            if site.element.name not in _an_here:
                _c = site_orth
                _an = [(n['distance'], (n['position'].x, n['position'].y, n['position'].z))
                       for n in unique_neighbors if n['element'] in _an_here]
                if len(_an) >= 2:
                    # Provisional: no valence exists yet, so no canonical CN
                    # and no per-bond valences. The inputs are kept so the
                    # same assessment can be redone once they do - see the
                    # re-assessment where site_result is built.
                    _EIR_GEOMETRY[site.label] = assess_site_geometry(
                        (_c.x, _c.y, _c.z), _an, site.element.name)
                    _EIR_GEOMETRY[site.label]['_geo_centre'] = (
                        _c.x, _c.y, _c.z)
                    _EIR_GEOMETRY[site.label]['_geo_neighbours'] = _an
                    _EIR_GEOMETRY[site.label]['_geo_element'] = site.element.name

            # v2.0.3: enumerate rather than unique_neighbors.index(neighbor),
            # which was an O(n^2) scan returning the index of the first EQUAL
            # element rather than of this one.
            for _ui, neighbor in enumerate(unique_neighbors):
                elem2 = neighbor['label']
                elem2_type = neighbor['element']
                distance = neighbor['distance']
                atom_type_pairs.add(tuple(sorted([elem1_type, elem2_type])))

                position_key = f"u{_ui}"
                symmetry_code = "supercell"

                _dbg(f"    -> {elem2} ({elem2_type}) dist={distance:.4f}")

                # Store bond
                bond_data['bond_label_1'].append(elem1)
                bond_data['bond_label_2'].append(elem2)
                bond_data['bond_distance'].append(f"{distance:.5f}")
                bond_data['bond_symmetry_2'].append(f"{symmetry_code}|{position_key}")
                bond_count += 1

        # v2.0.18: a step INSIDE a file, wearing the same tick as the
        # line that marks a file FINISHING. Behind VERBOSE, where _dbg
        # was waiting for it. The run log still records it.
        _dbg(f"  ✓ Calculated {bond_count} bonds using crystallographic symmetry (gemmi)")
        _dbg(f"  ✓ Bond types found: {sorted(atom_type_pairs)}")
        _dbg(f"  ✓ Space group: {small_struct.spacegroup_hm}")

        return bond_data

    except Exception as e:
        print(f"  ✗ Error calculating bonds with gemmi: {e}")
        import traceback
        traceback.print_exc()
        return None

def is_bond_data_present(data_block):
    """
    Check if a CIF data block contains pre-calculated bond distance data.

    Args:
        data_block: PyCifRW data block dictionary

    Returns:
        True if bond data present (GSAS-II style), False if missing (ICSD style)
    """
    required_keys = [
        '_geom_bond_atom_site_label_1',
        '_geom_bond_atom_site_label_2',
        '_geom_bond_distance',
        '_geom_bond_site_symmetry_2'
    ]

    return all(key in data_block for key in required_keys)

# ============================================================================
# DIRECTORY SELECTION DIALOG
# ============================================================================

def select_directory():
    """
    Opens a tkinter dialog to select a directory containing CIF files.
    Returns the selected directory path or None if cancelled.
    """
    import tkinter as tk
    from tkinter import filedialog

    root = tk.Tk()
    root.overrideredirect(True)
    root.attributes('-topmost', True)
    root.withdraw()

    print("\n" + "="*80)
    print("SELECT DIRECTORY CONTAINING CIF FILES")
    print("="*80)
    print("A file dialog will open. Please select the directory containing your CIF files.")
    print("(If the dialog appears behind other windows, check your taskbar)")

    directory_path = filedialog.askdirectory(
        title="Select Directory Containing CIF Files",
        mustexist=True
    )

    root.destroy()

    if not directory_path:
        print("\n✗ No directory selected. Exiting.")
        return None

    print(f"\n✓ Selected directory: {directory_path}")

    # Validate directory contains CIF files
    cif_files = list(Path(directory_path).glob("*.cif"))
    if not cif_files:
        print(f"\n✗ ERROR: No CIF files found in {directory_path}")
        print("Please select a directory containing .cif files")
        return None

    print(f"✓ Found {len(cif_files)} CIF files")
    _n=len(cif_files)
    print(f"  Rough estimate: ~{_n*0.9/60:.0f} min for large cells "
          f"(spinels/pyrochlores); simple oxides run several times faster.")

    return directory_path

