def process_single_cif(file_path, user_oxidation_states=None):
    """
    Process a single CIF file using validated Eir 1.0 logic.
    NEW in v1.2 continued: Mixed occupancy detection, Bosi (2014) strain analysis,
    and automatic 3D visualisation of problematic sites.
    NEW in v1.4: Structure-type specific analysis (spinel, perovskite, etc.)

    Args:
        file_path: Path to CIF file
        user_oxidation_states: Optional dict of {element: valence} overrides
                              If provided, these oxidation states will be used instead of database defaults

    Returns:
        dict with processing results including success status, metadata, sites data, and GII
    """
    results = {
        'success': False,
        'error': None,
        'metadata': {},
        'sites': [],
        'gii': None,
        'filename': os.path.basename(file_path)
    }

    # Parse CIF
    _LAST_PARSE_ERROR['reason'] = None
    # v2.0.44: filled by calculate_bonds_from_positions for THIS file only. A
    # CIF that brings its own bond list never reaches that function, and
    # must not inherit the previous file's record.
    _EIR_COLOCATED.clear()
    _EIR_ALTERNATIVES.clear()          # v2.0.46: likewise
    # v2.0.46: before parse_cif_file, which records shared anion positions.
    _USER_VALENCES.clear()
    _USER_VALENCES.update(user_oxidation_states or {})
    # v2.0.46: outside what bond valence sums describe, said before any of it
    # is computed (molecular_carbon, CELL 3)
    _mc = molecular_carbon(file_path)
    if _mc is not None:
        results['error'] = (f'Not assessed: {MOLECULAR_CARBON_NOTE}, '
                            f'{_mc[0]}-{_mc[1]} {_mc[2]:.3f} A. Covalent C-C, '
                            f'C-H and C-N bonds are outside what bond valence '
                            f'sums describe.')
        return results
    cif_obj = parse_cif_file(file_path)
    if cif_obj is None:
        results['error'] = ("Failed to parse CIF file: "
                            + (_LAST_PARSE_ERROR['reason'] or 'no reason recorded'))
        return results

    # Process first data block
    block_name = list(cif_obj.keys())[0]
    data_block = cif_obj[block_name]

    # v2.0.46: the alternative positions the bond finder set aside (G1)
    results['alternative_contacts_set_aside'] = _alternatives_summary()

    # Extract metadata
    results['metadata'] = {
        'block_name': block_name,
        'filename': os.path.basename(file_path),
        'chemical_formula': data_block.get("_chemical_formula_sum", "N/A"),
        'space_group': data_block.get("_space_group_name_H-M_alt",
                                     data_block.get("_symmetry_space_group_name_H-M", "N/A")),
    }

    # Extract ICSD publication metadata
    icsd_metadata = extract_icsd_metadata(file_path)
    results['metadata'].update({
        'icsd_code': icsd_metadata.get('icsd_code'),
        'year': icsd_metadata.get('year'),
        'journal': icsd_metadata.get('journal'),
        'authors': ', '.join(icsd_metadata.get('authors', [])) if icsd_metadata.get('authors') else None,
        'r_factor': icsd_metadata.get('r_factor'),
        'density': icsd_metadata.get('density'),
        'measurement_temperature_K': icsd_metadata.get('measurement_temperature_K'),
        'measurement_pressure_Pa': icsd_metadata.get('measurement_pressure_Pa'),
        'measurement_pressure_GPa': icsd_metadata.get('measurement_pressure_GPa'),
        'measurement_conditions': icsd_metadata.get('measurement_conditions')
    })

    # Validated Eir 1.0 workflow
    try:
        # Step 1: Extract site data
        initial_extracted_data = extract_initial_site_data(cif_obj)

        if not initial_extracted_data:
            results['error'] = "No data extracted from CIF"
            return results

        # Step 1.5 [v1.8.4]: element-level valences from the CIF, so that
        # classify_bond_pair can use its most reliable rule. Previously the
        # explicit-valence branch existed but was never given anything to work
        # with, and every pair fell through to the electronegativity heuristic.
        try:
            _cif_ox, _, _, _ = extract_cif_oxidation_states(file_path)
        except Exception:
            _cif_ox = None
        _pair_valences = dict(_cif_ox or {})
        if user_oxidation_states:
            _pair_valences.update(user_oxidation_states)
        # v2.0.46: before bond selection, which reads it (classify_bond_pair)
        _MIXED_SIGN_ELEMENTS.clear()
        _MIXED_SIGN_ELEMENTS.update(_mixed_sign_elements(file_path))

        # Step 2: Auto-select bond types
        data_with_selected_bonds = auto_select_bond_types(
            initial_extracted_data, valences=_pair_valences)

        if not data_with_selected_bonds[block_name].get('selected_bond_types_for_analysis'):
            results['error'] = ("No M-X bonds found"  # Updated to M-X (not just M-O)
                                + _unsupported_anion_note(_pair_valences))
            return results

        # Step 3: Auto-analyse coordination
        final_corrected_data = auto_analyze_coordination(data_with_selected_bonds)

        # Step 3.5 [NEW v1.4.2]: Extract per-atom valences for mixed-valence support
        per_atom_valences = extract_per_atom_valences(file_path)

        # Step 3.6 [NEW v1.7]: Extract site occupancies for integrity tier classification
        site_occupancies_data = extract_site_occupancies(file_path)

        # Step 4: Auto-assign valences (now with per-atom support)
        final_data_with_valences = auto_assign_valences(
            final_corrected_data,
            user_oxidation_states,
            per_atom_valences
        )

        # Step 5: Perform calculations
        calculated_results = perform_calculations_and_report(
        final_data_with_valences, site_occupancies=site_occupancies_data,
        colocated=dict(_EIR_COLOCATED))

        # Step 6: Calculate GII
        gii_results = calculate_global_instability_index(calculated_results, cif_path=file_path, per_atom_valences=per_atom_valences)

        # ============================================================================
        # Extract results for export WITH MIXED OCCUPANCY ANALYSIS
        # ============================================================================
        if block_name in calculated_results:
            for coords, site_data in calculated_results[block_name].items():
                labels = site_data.get('labels', ['unknown'])
                elements_at_site = site_data.get('elements', [])

                # ================================================================
                # v1.4.2 FIX: Iterate by LABEL, not by element
                # This ensures each site_label (e.g., Fe2, Fe3) gets its own row
                # with the correct element and explicit valence from the CIF
                # ================================================================
                for site_label in labels:

                    # ----------------------------------------------------------
                    # Determine element and valence for this specific label
                    # ----------------------------------------------------------
                    if per_atom_valences and site_label in per_atom_valences:
                        # Best case: found in per_atom_valences with explicit data
                        atom_info = per_atom_valences[site_label]
                        element = atom_info['element']
                        explicit_valence = atom_info['explicit_valence']
                        valence_source = 'cif_per_atom' if explicit_valence is not None else 'cif_inferred'
                    else:
                        # Fallback: try to match label to an element in the site's element list
                        element = None

                        # First try: label starts with element symbol (Fe1 -> Fe)
                        # v1.8.3 (A4): longest symbol first, so Cr is tested
                        # before C and Na before N.
                        for elem in sorted(elements_at_site, key=len, reverse=True):
                            if site_label.upper().startswith(elem.upper()):
                                element = elem
                                break

                        # Second try: use first element at site
                        if element is None and elements_at_site:
                            element = elements_at_site[0]
                            print(f"    ⚠ Warning: Could not match label '{site_label}' to element, using {element}")

                        # Last resort: extract from label string
                        if element is None:
                            element = re.sub(r'[0-9]+$', '', site_label)
                            element = element.capitalize() if len(element) > 1 else element.upper()

                        explicit_valence = None
                        valence_source = 'fallback'

                    # Skip if we couldn't determine element
                    if not element:
                        print(f"    ⚠ Skipping label '{site_label}' - could not determine element")
                        continue

                    # ----------------------------------------------------------
                    # Get element_data (BVS, CN, etc.) for this element
                    # ----------------------------------------------------------
                    elem_data = site_data['element_data'].get(element, {})

                    if not elem_data:
                        # Element wasn't analysed (e.g., no bonds found, or anion)
                        # Skip silently for anions, warn for cations
                        if element not in ['O', 'S', 'Se', 'Te', 'F', 'Cl', 'Br', 'I', 'N']:
                            print(f"    ⚠ No element_data for {element} at {site_label}")
                        continue

                    # ----------------------------------------------------------
                    # Override valence with explicit per-atom valence if available
                    # ----------------------------------------------------------
                    elem_data = elem_data.copy()  # Don't modify original
                    # v2.0.44: the valence R0 and b were read at, before the
                    # report substitutes the label's own. They now agree for
                    # every label; where they do not, it is said.
                    _sum_valence = elem_data.get('valence')
                    # One element at two valences on this position: this
                    # label's own sum (perform_calculations_and_report).
                    _byv = elem_data.get('bvs_by_valence')
                    if _byv and _cif_valence_is_usable(element, explicit_valence):
                        _kv = round(abs(float(explicit_valence)), 6)
                        if _kv in _byv:
                            elem_data['bvs'] = _byv[_kv]
                            elem_data['bvs_percent_diff'] = (
                                (_byv[_kv] - _kv) / _kv * 100
                                if _byv[_kv] is not None else None)
                            _sum_valence = explicit_valence

                    # A stated valence of zero is not an oxidation state
                    # assignment. ICSD entries routinely carry "Fe0+", "Na0+"
                    # or "Ba0+" where the depositor left it unset, and
                    # overwriting the computed valence with zero leaves the
                    # site with no usable deviation: the guard below skips the
                    # percentage, and |d1| is measured against nothing. On the
                    # 613-structure rock salt set this silently removed 73
                    # sites in 40 ordinary structures - NaCl, CaS, BaS - from
                    # the validation statistics. Keep the valence that was
                    # used for the calculation instead.
                    if _cif_valence_is_usable(element, explicit_valence):
                        elem_data['valence'] = explicit_valence
                        elem_data['valence_source'] = valence_source
                        if (_sum_valence is not None and abs(
                                abs(float(_sum_valence))
                                - abs(float(explicit_valence))) > 1e-6):
                            print(f"    Note: {site_label} summed with "
                                  f"{element}({_sum_valence}) parameters and "
                                  f"reported against {explicit_valence}.")
                    elif explicit_valence is not None:
                        elem_data['valence_source'] = 'cif_valence_ignored'

                        # Recalculate BVS percent diff with correct valence
                        bvs_val = elem_data.get('bvs')
                        if bvs_val is not None and explicit_valence != 0:
                            elem_data['bvs_percent_diff'] = (bvs_val - abs(explicit_valence)) / abs(explicit_valence) * 100
                    else:
                        elem_data['valence_source'] = valence_source

                    # ----------------------------------------------------------
                    # Get bond information for 3D visualisation
                    # ----------------------------------------------------------
                    bond_counts = None
                    full_site_info = None
                    cn_evidence = {}

                    if block_name in final_corrected_data:
                        for site_coords, site_info in final_corrected_data[block_name]['sites_with_bonds'].items():
                            if site_coords == coords:
                                if 'cn_and_bonds_by_type' in site_info:
                                    for (central_type, ligand_type), bond_analysis in site_info['cn_and_bonds_by_type'].items():
                                        if central_type == element:
                                            bond_counts = bond_analysis.get('confirmed_bond_counts', [])
                                            # v2.0.2: how the shell was decided
                                            cn_evidence = bond_analysis.get('cn_evidence') or {}
                                            break
                                full_site_info = site_info
                                break

                    # ========================================================================
                    # Mixed occupancy analysis (from the helper-functions cell)
                    # ========================================================================
                    mixed_occ_data = analyze_mixed_occupancy_at_site(
                        coords,
                        site_data,
                        final_corrected_data,
                        block_name,
                        data_block
                    )

                    # ========================================================================
                    # Calculate deviation and d1 (discrepancy factor from Bosi 2014)
                    # ========================================================================
                    bvs_val = elem_data.get('bvs')
                    valence = elem_data.get('valence')

                    if bvs_val is not None and valence is not None:
                        deviation = bvs_val - abs(valence)
                    else:
                        deviation = None

                    d1, abs_d1, bonding_state = calculate_discrepancy_factor(bvs_val, valence)

                    # ========================================================================
                    # Assign confidence flag based on disorder type and strain
                    # ========================================================================
                    confidence, bosi_likely, needs_review = assign_confidence_flag(
                        mixed_occ_data['disorder_type'],
                        mixed_occ_data['valence_difference'],
                        abs_d1,
                        deviation
                    )

                    # ========================================================================
                    # DATA INTEGRITY TIER ASSIGNMENT (NEW IN v1.7)
                    # ========================================================================
                    # Check minority species (I3) and mixed TM occupancy (FLAG)
                    site_occupancy = per_atom_valences[site_label]['occupancy'] if (per_atom_valences and site_label in per_atom_valences) else 1.0
                    is_minority = check_minority_species(site_label, per_atom_valences or {}, site_occupancies_data or {})
                    is_mixed_tm, has_noninteger_tm = check_mixed_tm_site(site_label, per_atom_valences or {}, site_occupancies_data or {})

                    # Get the CIF-assigned valence (before any override) for tier metadata
                    cif_valence = None
                    formal_valence_from_symbol = None
                    symbol_number_agreement = None

                    if per_atom_valences and site_label in per_atom_valences:
                        pav_info = per_atom_valences[site_label]
                        cif_valence = pav_info.get('explicit_valence')
                        # Parse integer from type_symbol for comparison
                        if pav_info.get('type_symbol'):
                            _, symbol_val = parse_atom_type_with_valence(pav_info['type_symbol'])
                            if symbol_val is not None:
                                formal_valence_from_symbol = int(symbol_val) if float(symbol_val) == int(symbol_val) else symbol_val
                            # Check agreement between symbol and oxidation_number
                            if cif_valence is not None and symbol_val is not None:
                                symbol_number_agreement = abs(cif_valence - symbol_val) < 0.05

                    # v2.0.11: no tier is assigned here. This cell computes
                    # EVIDENCE; the PGRM gates classify it in post-processing,
                    # where geometry decides severity before any chemistry is
                    # read. See the retirement note in CELL 1.
                    integrity_tier, flag_reason, flag_severity = None, None, None

                    # "What if": which integer oxidation state does the observed
                    # geometry support? Asked of any site whose assignment the
                    # depositor could not verify from diffraction - a shared
                    # transition-metal position, a non-integer partition, or a
                    # minority species - rather than of sites a bond valence
                    # threshold happened to flag.
                    whatif_result = {
                        'best_integer_valence': None,
                        'best_integer_deviation': None,
                        'candidates_tested': None,
                        'depositor_deviation': None,
                    }
                    if bvs_val is not None and (is_mixed_tm or has_noninteger_tm
                                                or is_minority):
                        whatif_result = whatif_analysis(element, bvs_val, valence)

                    # ========================================================================
                    # Build site result with ALL columns
                    # ========================================================================
                    site_result = {
                        # Original columns
                        'coords': coords,
                        'element': element,
                        'site_label': site_label,
                        'valence': elem_data.get('valence'),
                        'valence_source': elem_data.get('valence_source', 'unknown'),  # NEW in v1.4.2
                        'cn': elem_data.get('cn'),
                        'bvs': round(elem_data.get('bvs'), 4) if elem_data.get('bvs') is not None else None,
                        'bvs_percent_diff': round(elem_data.get('bvs_percent_diff'), 2) if elem_data.get('bvs_percent_diff') is not None else None,
                        'deviation': round(deviation, 4) if deviation is not None else None,

                        # Mixed occupancy columns
                        'has_mixed_occupancy': mixed_occ_data['has_mixed_occupancy'],
                        'occupancy_string': mixed_occ_data['occupancy_string'],
                        'n_elements_at_site': mixed_occ_data['n_elements_at_site'],
                        'disorder_type': mixed_occ_data['disorder_type'],
                        'valence_difference': round(mixed_occ_data['valence_difference'], 1) if mixed_occ_data['valence_difference'] else 0.0,
                        'max_valence_at_site': mixed_occ_data['max_valence_at_site'],
                        'min_valence_at_site': mixed_occ_data['min_valence_at_site'],

                        # Bosi (2014) strain indicators
                        'discrepancy_d1': round(d1, 4) if d1 is not None else None,
                        'abs_discrepancy_d1': round(abs_d1, 4) if abs_d1 is not None else None,
                        'bonding_state': bonding_state,

                        # Confidence & flagging
                        'confidence_flag': confidence,
                        'bosi_artifact_likely': bosi_likely,
                        'requires_manual_review': needs_review,

                        # Data integrity tier (NEW in v1.7)
                        'integrity_tier': integrity_tier,
                        'flag_reason': flag_reason,
                        'flag_severity': flag_severity,
                        'occupancy': round(site_occupancy, 4),
                        'is_minority_species': is_minority,
                        'is_mixed_occupancy_tm': is_mixed_tm,
                        'site_delta_v': round(mixed_occ_data['valence_difference'], 1) if mixed_occ_data['valence_difference'] else 0.0,
                        'cif_valence': cif_valence,
                        # v2.0.2: how far the stated valence sits from an
                        # integer, so a tier decided near the boundary is
                        # visible rather than silently on one side of it.
                        'valence_integer_distance': (
                            round(valence_integer_distance(cif_valence), 4)
                            if valence_integer_distance(cif_valence) is not None
                            else None),
                        'formal_valence_from_symbol': formal_valence_from_symbol,
                        'symbol_number_agreement': symbol_number_agreement,
                        # "What if" analysis (FLAG-tier sites only)
                        'best_integer_valence': whatif_result['best_integer_valence'],
                        'best_integer_deviation': whatif_result['best_integer_deviation'],
                        'candidates_tested': whatif_result['candidates_tested'],
                        'depositor_deviation': whatif_result['depositor_deviation'],

                        # Original columns
                        'ionic_potential': round(elem_data.get('ionic_potential'), 3) if elem_data.get('ionic_potential') is not None else None,
                        'cation_radius': round(elem_data.get('cation_radius'), 3) if elem_data.get('cation_radius') is not None else None,
                        'bld': round(elem_data.get('bond_length_distortion'), 6) if elem_data.get('bond_length_distortion') is not None else None,
                        'bvs_unweighted': round(elem_data.get('bvs_unweighted'), 4) if elem_data.get('bvs_unweighted') is not None else None,
                        'cn_occupancy_weighted': elem_data.get('cn_occupancy_weighted'),
                        'ligand_occupancy_clamped': elem_data.get('ligand_occupancy_clamped'),
                        'ligand_types': ','.join(elem_data.get('ligand_types', [])) or None,
                        'fields_describe_ligand': elem_data.get('fields_describe_ligand'),
                        'bvs_distance_ratio': None,
                        'bvs_geometry_plausible': None,
                        # Coordination shell provenance (NEW in v2.0.2). A CN
                        # revision is never silent: these say what the gap
                        # analysis returned, what ECoN said about it, and
                        # whether the shell was extended.
                        'cn_gap': cn_evidence.get('cn_gap'),
                        'cn_revised': cn_evidence.get('cn_revised'),
                        'cn_revision_reason': cn_evidence.get('cn_revision_reason'),
                        'econ_shell': cn_evidence.get('econ_shell'),
                        'cn_shell_max': cn_evidence.get('cn_shell_max'),
                        'cn_tie_extended': cn_evidence.get('cn_tie_extended', False),
                        'cn_before_ties': cn_evidence.get('cn_before_ties'),
                        # Dual-shell diagnostic (NEW in v2.0.2). The same sum
                        # over the full distance shell, so that the shell
                        # convention can be tested within a structure rather
                        # than by comparing structures that differ in both
                        # coordination number and chemistry.
                        'cn_full_shell': elem_data.get('cn_full_shell'),
                        'bvs_full_shell': (round(elem_data['bvs_full_shell'], 4)
                                           if elem_data.get('bvs_full_shell') is not None else None),
                        'bvs_full_shell_percent_diff': (
                            round(elem_data['bvs_full_shell_percent_diff'], 2)
                            if elem_data.get('bvs_full_shell_percent_diff') is not None else None),
                        'bvs_shell_delta': (round(elem_data['bvs_shell_delta'], 4)
                                            if elem_data.get('bvs_shell_delta') is not None else None),
                        # v2.0.3: the bond-valence shell, and the ECoN-weighted
                        # sum that needs no shell at all.
                        'cn_method': elem_data.get('cn_method'),
                        'cn_bv_shell': elem_data.get('cn_bv_shell'),
                        'bv_shell_max_distance': elem_data.get('bv_shell_max_distance'),
                        'bv_shell_last_s': elem_data.get('bv_shell_last_s'),
                        'bv_shell_next_s': elem_data.get('bv_shell_next_s'),
                        'cn_shell_confidence':
                            elem_data.get('cn_shell_confidence'),
                        'bvs_bv_shell': (round(elem_data['bvs_bv_shell'], 4)
                                         if elem_data.get('bvs_bv_shell') is not None else None),
                        'bvs_bv_shell_percent_diff': (
                            round(elem_data['bvs_bv_shell_percent_diff'], 2)
                            if elem_data.get('bvs_bv_shell_percent_diff') is not None else None),
                        'cn_gap_shell': elem_data.get('cn_gap_shell'),
                        'bvs_gap_shell': (round(elem_data['bvs_gap_shell'], 4)
                                          if elem_data.get('bvs_gap_shell') is not None else None),
                        'bvs_gap_shell_percent_diff': (
                            round(elem_data['bvs_gap_shell_percent_diff'], 2)
                            if elem_data.get('bvs_gap_shell_percent_diff') is not None else None),
                        'bvs_gap_shell_delta': (round(elem_data['bvs_gap_shell_delta'], 4)
                                                if elem_data.get('bvs_gap_shell_delta') is not None else None),
                        # v2.0.7: the adaptive cut-off, reported not canonical.
                        'cn_bv_adaptive': elem_data.get('cn_bv_adaptive'),
                        'bv_boundary_adaptive': elem_data.get('bv_boundary_adaptive'),
                        'bv_boundary_source': elem_data.get('bv_boundary_source'),
                        'bv_cut_iterations': elem_data.get('bv_cut_iterations'),
                        'bvs_bv_adaptive': (round(elem_data['bvs_bv_adaptive'], 4)
                                            if elem_data.get('bvs_bv_adaptive') is not None else None),
                        'bvs_bv_adaptive_percent_diff': (
                            round(elem_data['bvs_bv_adaptive_percent_diff'], 2)
                            if elem_data.get('bvs_bv_adaptive_percent_diff') is not None else None),
                        'bvs_econ_weighted': (round(elem_data['bvs_econ_weighted'], 4)
                                              if elem_data.get('bvs_econ_weighted') is not None else None),
                        'bvs_econ_weighted_percent_diff': (
                            round(elem_data['bvs_econ_weighted_percent_diff'], 2)
                            if elem_data.get('bvs_econ_weighted_percent_diff') is not None else None),
                        'econ_weighted_cn': (round(elem_data['econ_weighted_cn'], 3)
                                             if elem_data.get('econ_weighted_cn') is not None else None),
                        'site_bvs_averaged': None,
                        'site_expected_averaged': None,
                        'site_deviation_averaged': None,
                        # v2.0.44: the valence the parameters were read at,
                        # and where it came from; the species added from a
                        # shared anion position; the void guard's evidence.
                        'bvs_valence': _sum_valence,
                        'bvs_valence_source': ((full_site_info or {})
                                               .get('valence_sources', {})
                                               .get(element)),
                        'colocated_ligands': elem_data.get('colocated_ligands'),
                        'ligand_occupancy_conditional':                  # v2.0.46
                            elem_data.get('ligand_occupancy_conditional'),
                        'colocated_unparameterised':
                            elem_data.get('colocated_unparameterised'),
                        'cn_before_void_guard':
                            elem_data.get('cn_before_void_guard'),
                        'shell_void_ratio': elem_data.get('shell_void_ratio'),
                        'shell_void_limit': elem_data.get('shell_void_limit'),
                        'shell_void_next': elem_data.get('shell_void_next'),
                        'shell_void_reference_max':
                            elem_data.get('shell_void_reference_max'),
                    }

                    # Add Shannon-Prewitt data if available (unchanged)
                    if 'shannon_diffs' in elem_data and elem_data['shannon_diffs']:
                        avg_shannon_diff = np.mean([s['percent_diff'] for s in elem_data['shannon_diffs']])
                        site_result['shannon_diff'] = round(avg_shannon_diff, 2)
                        site_result['avg_bond_length'] = round(np.mean([s['observed_distance'] for s in elem_data['shannon_diffs']]), 4)
                        site_result['min_bond_length'] = round(min(s['observed_distance'] for s in elem_data['shannon_diffs']), 4)
                        site_result['shannon_source'] = elem_data.get('shannon_source')

                    # ====================================================
                    # v2.0.5: OBSERVED AGAINST MEASURED, IN ANGSTROMS
                    #
                    # Reported, never flagged. The obvious screen here - 'is
                    # any bond outside the range ever observed for this ion' -
                    # was built and rejected, and the reason is worth keeping.
                    # An extreme-value statistic needs a large sample, and
                    # Gagne's high-CN configurations are precisely the small
                    # ones: La(3+) reaches n >= 30 only at CN 8 and 9, while
                    # the perovskite A site sits at 10 to 12. On the
                    # 938-structure ICSD perovskite set that screen condemned
                    # 224 sites in structures passing every other test, some
                    # with GII below 0.02. The reference tail is missing where
                    # it is most needed and no threshold repairs that.
                    #
                    # What survives is the report. A difference in angstroms
                    # beside a stated sample size is something a reader can
                    # weigh; a ratio against a fitted threshold is not. On
                    # that dataset 96.9% of sites resolve to a measured
                    # expectation at tier 1 or 2.
                    #
                    # bl_ratio_min is the one genuinely parameter-free
                    # quantity: this site's shortest contact against the
                    # shortest ever observed for this exact ion
                    # configuration. Like against like, so it carries no
                    # coordination dependence - measured at 1.014 to 1.049
                    # across CN 6 to 12, against 0.976 falling to 0.881 for
                    # the Shannon ratio the radii screen uses. It is computed
                    # only where the sample supports the tail
                    # (BL_MIN_SAMPLE), which is 66% of B sites and 12% of A
                    # sites here. Null means the tail is not characterised;
                    # that is a fact about the reference data, not a failure.
                    # ====================================================
                    _bl_lig = (elem_data.get('ligand_type')
                               or (str(site_result.get('ligand_types') or 'O')
                                   .split(',')[0]) or 'O')
                    _bl = expected_bond_length(element, valence,
                                               site_result.get('cn'), _bl_lig)
                    if _bl:
                        site_result['bl_expected_mean'] = _bl['mean']
                        site_result['bl_expected_sd'] = _bl['sd']
                        site_result['bl_expected_min'] = _bl['min']
                        site_result['bl_n_bonds'] = _bl['n_bonds']
                        site_result['bl_source'] = _bl['source']
                        site_result['bl_tier'] = _bl['tier']
                        # v2.0.46: always present, null where not computable.
                        # A configuration with too few bonds for a minimum
                        # (Cr(4+)O6 has six) left bl_ratio_min out of the
                        # row, so a run in which no site had one had no such
                        # column, and CELL 14 stopped on it with a KeyError
                        # (ICSD 35327, CrO2, run on its own).
                        site_result['bl_delta_mean'] = None
                        site_result['bl_ratio_min'] = None
                        site_result['bl_delta_min'] = None
                        _obs_mean = site_result.get('avg_bond_length')
                        _obs_min = site_result.get('min_bond_length')
                        if _obs_mean is not None:
                            site_result['bl_delta_mean'] = round(
                                _obs_mean - _bl['mean'], 4)
                        if _obs_min is not None and _bl['min']:
                            site_result['bl_ratio_min'] = round(
                                _obs_min / _bl['min'], 4)
                            site_result['bl_delta_min'] = round(
                                _obs_min - _bl['min'], 4)
                        # v2.0.36: the same difference in units of the spread
                        # Gagne actually observes for this configuration.
                        # bl_delta_mean says a polyhedron is 0.11 A small;
                        # this says whether that is unremarkable (Mn(III)O6,
                        # sd 0.149) or a 4.5 sigma event (Sn(IV)O6, sd 0.024).
                        # The sample rule is NOT applied here: this stays a
                        # measurement, and M10 in CELL 7b decides what is
                        # eligible to be judged on it.
                        if (_obs_mean is not None and _bl['sd']
                                and _bl['sd'] > 0):
                            site_result['bond_size_z'] = round(
                                (_obs_mean - _bl['mean']) / _bl['sd'], 3)


                    # ========================================================================
                    # 3D visualisation for problematic sites
                    # ========================================================================
                    if (deviation is not None and abs(deviation) > 0.30
                            and PY3DMOL_AVAILABLE and bond_counts
                            and may_visualise()):
                        print(f"\n    ⚠️  Significant BVS deviation detected for {element} site!")
                        print(f"        BVS: {bvs_val:.3f}  │  Expected: {valence:+g}  │  Δ: {deviation:+.3f} v.u.")

                        # NEW: Print diagnostic information
                        if d1 is not None:
                            print(f"        d1: {d1:+.3f} v.u. ({bonding_state})")
                        print(f"        Disorder: {mixed_occ_data['disorder_type']}", end="")
                        if mixed_occ_data['valence_difference'] > 0:
                            print(f" (ΔV={mixed_occ_data['valence_difference']:.0f})")
                        else:
                            print()
                        print(f"        Occupancy: {mixed_occ_data['occupancy_string']}")
                        print(f"        Confidence: {confidence}")
                        if bosi_likely:
                            print(f"        ⚠️  Bosi artifact likely - spectroscopy required!")

                        print(f"    [Generating 3D visualisation...]")

                        try:
                            visualize_problematic_site_3d(
                                cif_path=file_path,
                                element=element,
                                site_label=site_label,
                                bonds_info=bond_counts,
                                deviation=deviation,
                                formal_charge=valence,
                                bvs_value=bvs_val,
                                filename=os.path.basename(file_path)
                            )
                        except Exception as viz_error:
                            print(f"    [3D visualisation failed: {viz_error}]")

                    elif (deviation is not None and abs(deviation) > 0.30
                          and not PY3DMOL_AVAILABLE):
                        print(f"\n    ⚠️  Significant deviation ({deviation:+.3f} v.u.)")
                        if d1 is not None:
                            print(f"        d1: {d1:+.3f} v.u. ({bonding_state})")
                        print(f"        Disorder: {mixed_occ_data['disorder_type']}")
                        print(f"        Confidence: {confidence}")
                        print(f"        Install py3Dmol for 3D visualisation")

                    # v2.0.13: re-assess the geometry with the CANONICAL
                    # coordination number and the real per-bond valences.
                    #
                    # assess_site_geometry runs during bond calculation,
                    # before any valence is assigned, so its first pass uses
                    # a provisional shell (1.35 x d_ref, capped at 3.5 A).
                    # That shell disagrees with the canonical one on 706 of
                    # 1895 perovskite sites, 37%, which meant geo_bond_min,
                    # geo_bond_max, the distortion indices and cshm were all
                    # computed over a DIFFERENT polyhedron from the bond
                    # valence sum beside them - including the two columns
                    # bl_ratio_min is compared against.
                    _geo = dict(_EIR_GEOMETRY.get(site_label, {}))
                    _gc = _geo.pop('_geo_centre', None)
                    _gn = _geo.pop('_geo_neighbours', None)
                    _ge = _geo.pop('_geo_element', None)
                    _gcn = site_result.get('cn')
                    # Per-bond valences s_i = exp((R0 - d)/b), computed here
                    # because R0 and b are not carried past the element loop.
                    # Without them bv_vector_sum would stay None for ever,
                    # which is how the column came to hold the geometric
                    # eccentricity under a bond-valence name in the first
                    # place.
                    _r0, _bb = elem_data.get('bv_r0'), elem_data.get('bv_b')
                    _geo_valences = None
                    if _gn and _r0 is not None and _bb:
                        _geo_valences = [math.exp((_r0 - _d) / _bb)
                                         for _d, _ in sorted(_gn,
                                                             key=lambda t: t[0])]
                    if _gc and _gn and _gcn:
                        try:
                            _geo = assess_site_geometry(
                                _gc, _gn, _ge, cn=_gcn,
                                valences=_geo_valences)
                        except (TypeError, ValueError, IndexError) as _e:
                            _geo['geo_reassess_error'] = (
                                f'{type(_e).__name__}: {_e}')
                    site_result.update(_geo)
                    results['sites'].append(site_result)

        # Add GII (unchanged)
            if block_name in gii_results:
                results['gii'] = gii_results[block_name].get('gii')
                results['wagii'] = gii_results[block_name].get('wagii')
                results['n_sites_zero_occupancy'] = gii_results[block_name].get(
                    'n_sites_zero_occupancy')
                # v2.0.15: exported, because a GII computed over fewer sites
                # than the structure has is a different quantity and the
                # reader must be able to see that it happened.
                results['n_sites_below_floor'] = gii_results[block_name].get(
                    'n_sites_below_floor')
                # The index as it was computed before v2.0.15, so the change
                # can be checked against the previous run rather than taken
                # on trust. Equal to gii wherever nothing was excluded.
                results['gii_with_floor_failures'] = gii_results[block_name].get(
                    'gii_with_floor_failures')
                results['bvs_discrepancy'] = gii_results[block_name].get('bvs_discrepancy')
                for _bk in ('bvs_discrepancy_weighted', 'gii_bondstr_old',
                            'gii_bondstr_a', 'gii_bondstr_b', 'gii_bondstr_c',
                            'gii_bondstr_convention',
                            'gii_bondstr_mult_source',
                            'gii_bondstr_n_no_mult'):
                    results[_bk] = gii_results[block_name].get(_bk)
                results['stability_assessment'] = gii_results[block_name].get('stability_assessment')

        # =====================================================================
        # SITE-AVERAGED DEVIATION ON SHARED SITES
        # =====================================================================
        # A site shared by two species is reported once per species, with each
        # species' bond valence sum computed at the SAME geometry using its own
        # R0. So a 1.6% Ti anti-site impurity in NaTiO2 is asked what its sum
        # would be if it owned a sodium-sized site, returns 1.55 against an
        # expected 3.0, and that -1.45 deviation is then weighted EQUALLY with
        # the 98.4% majority. ICSD 85657 comes out at GII 1.02 for a compound
        # that is essentially ordered.
        #
        # Below, each crystallographic site gets one deviation, from the
        # occupancy-weighted combination of the per-species sums that Eir has
        # already computed. That gives 0.17 for the same structure.
        #
        # Note it combines the REPORTED sums rather than recomputing from the
        # mean bond length. Recomputing looks equivalent and is not: a
        # Jahn-Teller site with 4 short and 2 long bonds has a bond valence sum
        # of 2.94, while six bonds evaluated at the mean distance give 2.15,
        # because the exponential is convex. Doing it that way turned three
        # ordered manganates from GII 0.13 into 1.03.
        #
        # Reported alongside gii, not replacing it. The residual gap between
        # ordered and shared sites is not yet explained, so both should stay
        # visible.
        try:
            _by_site = {}
            for _s in results['sites']:
                _by_site.setdefault(str(_s.get('coords')), []).append(_s)

            # `x or 1.0` treats a refined occupancy of 0.0 as full, because
            # 0.0 is falsy. CIFs declare zero-occupancy placeholder sites to
            # describe an anti-site model: ICSD 138129 has Yb2 at 16c with
            # occupancy 0, whose bond valence sum is 6.87 v.u. against a formal
            # 3 because ytterbium does not fit a titanium octahedron. Weighted
            # as if fully present, it took that site's expected valence from
            # 4.0 to 3.4996 and the site-averaged GII from about 0.46 to 1.57,
            # which is how gii_site_averaged came to exceed wagii on a
            # structure it should have agreed with.
            #
            # None still means "not stated", and that does default to full.
            def _occ_of(g):
                v = g.get('occupancy')
                if v is None:
                    return 1.0
                try:
                    v = float(v)
                except (TypeError, ValueError):
                    return 1.0
                return 1.0 if v != v else v

            _site_devs = []
            for _coords, _grp in _by_site.items():
                _w = sum(_occ_of(g) for g in _grp)
                if not _w:
                    continue
                if any(g.get('bvs') is None or g.get('valence') is None for g in _grp):
                    continue
                _bvs_site = sum(_occ_of(g) * g['bvs'] for g in _grp) / _w
                _exp_site = sum(_occ_of(g) * abs(g['valence']) for g in _grp) / _w
                _dev = _bvs_site - _exp_site
                _site_devs.append(_dev)
                for g in _grp:
                    g['site_bvs_averaged'] = round(_bvs_site, 4)
                    g['site_expected_averaged'] = round(_exp_site, 4)
                    g['site_deviation_averaged'] = round(_dev, 4)

            if _site_devs:
                results['gii_site_averaged'] = round(
                    math.sqrt(sum(x * x for x in _site_devs) / len(_site_devs)), 6)
                results['n_crystallographic_sites'] = len(_site_devs)
            else:
                results['gii_site_averaged'] = None
                results['n_crystallographic_sites'] = None
        except Exception as _e:
            results['gii_site_averaged'] = None
            results['n_crystallographic_sites'] = None
            print(f"  [site-averaged GII unavailable: {_e}]")

        # CIF charge-sign errors found while selecting bond pairs THIS
        # structure. v2.0.27: cleared at the top of this function, so this is
        # no longer everything seen since the batch began.
        if _SIGN_INVERSIONS:
            results['cif_sign_inversion'] = True
            results['cif_sign_inversion_detail'] = '; '.join(
                f"{e}{v:+g} in a {'/'.join(p)} pair" for p, (e, v) in _SIGN_INVERSIONS.items())
            print(f"\n  CIF CHARGE SIGNS INVERTED: "
                  f"{results['cif_sign_inversion_detail']}.")
            print(f"  The negative charge is assigned to the less electronegative "
                  f"species, which cannot be right. The CIF's oxidation states have "
                  f"been ignored for these pairs and the assignment made from "
                  f"electronegativity instead. This is an error in the deposited "
                  f"entry, not in the structure.")
        else:
            results['cif_sign_inversion'] = False
            results['cif_sign_inversion_detail'] = None

        # anion-anion screen: the only test here that looks at the anion
        # sublattice rather than outward from a cation. v2.0.46: told which
        # species the CIF states are anions (see _packing_valences).
        _aa, _cc = anion_anion_contacts(
            file_path, valences=_packing_valences(file_path, _pair_valences))
        # v2.0.14: `if _aa` discards a measured 0.0 as though it were
        # absent. dedup_tol keeps 0.0 from arising today, so this is a
        # correctness fix rather than a behaviour change - but 'no value'
        # and 'zero' must not be the same test in a function whose None
        # switches a gate off.
        results['anion_anion_min'] = None if _aa is None else round(_aa, 4)
        results['cation_cation_min'] = None if _cc is None else round(_cc, 4)
        # v2.0.46: the floor depends on the pair (MONOVALENT_PAIR_MIN), so
        # the contact nearest its own floor decides, and is reported
        _gv = _CATION_CONTACT.pop(str(file_path), None)
        results['cation_cation_contact'] = (
            None if _gv is None else
            f'{_gv[2]}-{_gv[3]} {_gv[1]:.3f} A, floor {_gv[4]:.2f} A'
            + (f'; positions {_gv[5]:.3f} and {_gv[6]:.3f} filled'
               if _gv[7] else ''))
        # v2.0.46: below the floor, but between mobile ions (mobile_pair)
        results['cation_contact_partly_occupied'] = (
            None if _gv is None else bool(_gv[7]))
        # v2.0.46: the shortest polyanion edge the scan set aside, if any
        _pe = _POLYANION_EDGE_MIN.pop(str(file_path), None)
        results['polyanion_edge_min'] = None if _pe is None else round(_pe, 4)

        # v2.0.12: the anion's free positional parameter, where the structure
        # type defines one. Computed since v1.8.3 and never wired: it was
        # reachable only through extract_all_structural_parameters, which
        # nothing called. Reported, not screened.
        try:
            _ap = extract_anion_parameter(file_path)
        except (OSError, UnicodeDecodeError, ValueError, TypeError,
                IndexError, KeyError) as _e:
            _note_read_failure(file_path, 'anion_parameter', _e)
            _ap = {}
        for _k in ('u_parameter', 'u_deviation', 'u_eff', 'delta_u',
                   'origin_choice', 'anion_wyckoff', 'anion_site_swapped',
                   'pyrochlore_48f_x', 'pyrochlore_fluorite_limit',
                   'u_parameter_applicable', 'u_note'):
            results[_k] = _ap.get(_k)
        results['anion_packing_plausible'] = (
            None if _aa is None else bool(ge(_aa, ANION_ANION_MIN)))
        if results['anion_packing_plausible'] is False:
            print(f"\n  ANION CONTACT TOO SHORT: two anions {_aa:.3f} A apart. "
                  f"Below {ANION_ANION_MIN} A their electron clouds overlap by more "
                  f"than any observed oxide.")
            print(f"  Neither cation-based screen can see this. Check the "
                  f"coordinates and the symmetry expansion.")

        # v2.0.12: the cation sublattice floor. cation_cation_min has been
        # computed and exported since v2.0.2 and nothing ever read it. On the
        # three reference families it catches 59 structures, 19 of which no
        # other screen sees, including two that sat in the triage's
        # UNEXPLAINED bucket: ICSD 133663 (NdNiO3, Nd-Ni 1.912 A) and 13793
        # (SrSnO3, Sn-Sr 2.019 A). See CATION_CATION_MIN for the measurement.
        # v2.0.15: CATION_CATION_MIN does not apply to hydrogen; see the
        # constant. anion_anion_contacts excludes H from the cation bucket,
        # so _cc never carries an H contact and this test is unchanged for
        # every structure in the three reference families, none of which
        # contains hydrogen.
        results['cation_packing_plausible'] = (
            None if _cc is None else
            bool(ge(_gv[1], _gv[4])) if _gv is not None else
            bool(ge(_cc, CATION_CATION_MIN)))
        if results['cation_packing_plausible'] is False:
            _d, _fl = (_gv[1], _gv[4]) if _gv is not None else (_cc, CATION_CATION_MIN)
            print(f"\n  CATION CONTACT TOO SHORT: two cations {_d:.3f} A "
                  f"apart, below the {_fl:.2f} A floor for the pair.")
            print(f"  Cations repel; edge- and face-sharing polyhedra bring "
                  f"them to 2.6-3.0 A and no closer. A contact below this is "
                  f"a coordinate or symmetry fault, not chemistry.")
            print(f"  Split sites are already exempt: a single atom modelled "
                  f"as two partly-occupied positions is not two cations.")

        # v1.8.6: geometry screen, in the core path.
        # This test previously lived only in add_coordination_quality, so a
        # single-structure analysis had no sanity check at all: a CIF with a
        # 0.5 A cation-anion contact returned success=True and a GII in the
        # hundreds, with nothing to say the geometry was impossible. Ions have
        # a finite size, so a contact much below the sum of their radii cannot
        # be real, and a bond valence built on it is meaningless.
        # v2.0.2: which species dominates each crystallographic position.
        #
        # The geometry screens ask whether a bond length can be real. A
        # minority species has no geometry of its own: it sits in the cavity
        # the majority defines, so the question becomes whether the WRONG ion
        # fits, and the answer is no -- which is why it is a minority. ICSD
        # 119363 (Lu2Ti2O7) is condemned by Lu2 at 0.8% occupancy on the
        # titanium site, ratio 0.869 against a 0.900 threshold, while every
        # species actually present passes: Lu1 0.929, Ti2 0.984, Ti1 1.055.
        #
        # Across the ICSD pyrochlore set, 32 of the 95 bond-valence distance
        # failures and 8 of the 51 radii failures are structures in which every
        # failing site is below 5% occupancy.
        #
        # The per-site verdicts are unchanged and still exported; only the
        # STRUCTURE-level roll-up is restricted to the dominant species. Where
        # no species reaches half a position, the most abundant one is used, so
        # a three-way split still contributes.
        _pos_max = {}
        for _s in results['sites']:
            _k = str(_s.get('coords'))
            try:
                _o = float(_s.get('occupancy') if _s.get('occupancy') is not None else 1.0)
            except (TypeError, ValueError):
                _o = 1.0
            if _k not in _pos_max or _o > _pos_max[_k]:
                _pos_max[_k] = _o
        for _s in results['sites']:
            try:
                _o = float(_s.get('occupancy') if _s.get('occupancy') is not None else 1.0)
            except (TypeError, ValueError):
                _o = 1.0
            _s['is_dominant_species'] = bool(
                _o >= _pos_max.get(str(_s.get('coords')), _o) - 1e-9)

        _worst_ratio, _worst = None, None
        _worst_bratio, _worst_b = None, None
        # v2.0.2: track the worst MARGIN against each site's own threshold, not
        # the worst raw ratio. Once the threshold varies with coordination the
        # smallest ratio is no longer the worst offender: a twelve-coordinate
        # site at 0.85 is comfortably inside its 0.792 threshold while a
        # six-coordinate site at 0.88 is outside its 0.900.
        _worst_bmargin = None
        _bvs_any_fail = False
        # v2.0.3: the radii screen now has a per-site threshold, so the worst
        # site is the one with the smallest MARGIN, not the smallest ratio.
        _worst_cmargin = None
        _core_any_fail = False
        _cn_implausible = []
        for _s in results['sites']:
            # Coordination plausibility. Independent of every test below,
            # which all ask whether a contact is too short; this asks whether
            # bonds are missing.
            _cnp, _cnlo, _cnhi = coordination_plausible(
                _s.get('element'), _s.get('valence'), _s.get('cn'))
            _s['cn_plausible'] = _cnp
            _s['cn_shannon_min'] = _cnlo
            _s['cn_shannon_max'] = _cnhi
            if _cnp is False and _s.get('is_dominant_species', True):
                _cn_implausible.append(_s)
            _d = _s.get('min_bond_length') or _s.get('avg_bond_length')

            # v2.0.3 (rule 1). The absolute floor, tested before anything that
            # divides by a radius or a bond valence parameter. A contact below
            # CATION_ANION_ABSOLUTE_MIN is not a short bond, it is not a bond,
            # and no sum built on it means anything. The all_cations variant of
            # ICSD 11616 produced a Dy-O contact of 1.181 A, from which a shell
            # of one was built and the site reported as overbonded at 8.258 v.u.
            # v2.0.46: not for hydrogen. O-H is about 0.97 A by neutrons and
            # shorter by X-rays, and is a bond: Mg(OH)2 with its H located
            # came out EXPUNGE on G1 at 0.979 A.
            _s['contact_above_floor'] = (
                None if (_d is None or _s.get('element')
                         in CATION_FLOOR_EXCLUDED_ELEMENTS)
                else bool(_d >= CATION_ANION_ABSOLUTE_MIN))
            if _s['contact_above_floor'] is False:
                _s['cn_plausible'] = False
                _s['bonding_state'] = 'not_a_coordination_environment'
                if (_s.get('is_dominant_species', True)
                        and not any(_x is _s for _x in _cn_implausible)):
                    _cn_implausible.append(_s)

            _lig = (_s.get('fields_describe_ligand')
                    or (_s.get('ligand_types') or 'O').split(',')[0] or 'O')
            _ratio, _expected, _rsrc = core_radii_ratio(
                _s.get('element'), _lig, _d,
                valence=_s.get('valence'), cn=_s.get('cn'))
            _s['core_expected_contact'] = (round(_expected, 4)
                                           if _expected else None)
            _s['core_radii_source'] = _rsrc
            if _ratio is None:
                # UNTESTED, not passed. Recorded so it cannot be mistaken for
                # a clean result downstream.
                _s['core_shortest_contact_ratio'] = None
                _s['core_geometry_plausible'] = None

            # Parameter-based ratio. Runs whether or not a radius was found,
            # because it needs none; that is the point of it.
            #
            # `_d` is tested here explicitly. Until v2.0.2 this block sat below
            # a `continue` that fired when no ionic radius was available, and
            # that continue was doing two jobs: gating this screen on the radii
            # table (the fault it was removed to fix) and, incidentally,
            # guaranteeing `_d` was not None before the division below.
            # Removing it un-gated the screen as intended and dropped the null
            # check with it, which cost five structures with an unhandled
            # TypeError. A guard should never be load-bearing by accident.
            _v, _cn = _s.get('valence'), _s.get('cn')
            # v2.0.23 (item 4): THE ANION WAS HARD-CODED TO OXYGEN.
            #
            # `_lig` is resolved four lines above and handed to the radii
            # screen. This screen was given the string 'O' instead, so for a
            # sulfide or a selenide it divided a real S or Se contact by an
            # OXIDE d_ideal. R0(S) exceeds R0(O) by roughly 0.4 A, so the
            # ratio comes out high and the site always passes: the screen was
            # not lenient on non-oxides, it was absent from them, and it said
            # nothing about being absent.
            #
            # That is the same failure the radii-ratio screen shows from the
            # other side - its only four exclusive catches in 3291 structures
            # are Ag(1+), Cu(1+) and Fe(2+) SULFIDES, where hard-sphere radii
            # are meaningless and bond-valence distance passed all four at
            # 0.97 to 1.10. A calibrated quantity used out of its domain is
            # the standing hazard in this tool, and silence about it is worse
            # than the error.
            #
            # bvs_distance_anion now records what was actually tested, and
            # bvs_distance_untested names the sites no parameters exist for,
            # so an absent screen is visible in the CSV rather than
            # indistinguishable from a passed one.
            _s['bvs_distance_anion'] = _lig
            if _v and _cn and _d:
                _r0b = get_bv_parameters_fractional(_s.get('element'), _v, _lig)
                _have_bv = bool(_r0b) and _r0b[0] is not None
                if not _have_bv:
                    _s['bvs_distance_untested'] = (
                        f'no bond valence parameters for '
                        f'{_s.get("element")}({_v}) with {_lig}')
                if _have_bv:
                    _R0, _b = _r0b
                    _d_ideal = _R0 - _b * math.log(abs(_v) / _cn)
                    if _d_ideal > 0:
                        _bratio = _d / _d_ideal
                        _s['bvs_distance_ratio'] = round(_bratio, 4)
                        _s['bvs_distance_threshold'] = round(
                            bvs_distance_threshold(_cn), 4)
                        _s['bvs_geometry_plausible'] = bool(
                            ge(_bratio, _s['bvs_distance_threshold']))
                        if not _s['bvs_geometry_plausible'] and                                 _s['is_dominant_species']:
                            _bvs_any_fail = True
                        _bmargin = _bratio - _s['bvs_distance_threshold']
                        if _s['is_dominant_species'] and (
                                _worst_bmargin is None or _bmargin < _worst_bmargin):
                            _worst_bmargin = _bmargin
                            _worst_bratio = _bratio
                            _worst_b = _s
            # v1.8.8: named core_* so they cannot collide with the columns
            # add_coordination_quality writes. Both compute the same quantity
            # by different routes, and the post-processor runs second, so
            # sharing a name meant one silently overwrote the other with no
            # way to tell which you were reading. They currently agree to
            # 0.0001; keeping both visible means a future divergence is
            # informative rather than invisible.
            if _ratio is not None:
                _s['core_shortest_contact_ratio'] = round(_ratio, 4)
                _s['core_contact_threshold'] = round(
                    radii_contact_threshold(_s.get('cn')), 4)
                _s['core_geometry_plausible'] = bool(
                    ge(_ratio, _s['core_contact_threshold']))
                if not _s['core_geometry_plausible'] and _s['is_dominant_species']:
                    _core_any_fail = True
                # structure verdict from the dominant species only, and by
                # MARGIN: with a per-site threshold the lowest ratio is no
                # longer necessarily the site that failed.
                _cmargin = _ratio - _s['core_contact_threshold']
                if _s['is_dominant_species'] and (
                        _worst_cmargin is None or _cmargin < _worst_cmargin):
                    _worst_cmargin, _worst_ratio, _worst = _cmargin, _ratio, _s
        # How many sites could not be tested at all. A structure whose every
        # site is untested is not a structure that passed.
        results['core_sites_untested'] = sum(
            1 for _s in results['sites']
            if _s.get('core_radii_source') == 'untested')
        results['core_sites_tested'] = sum(
            1 for _s in results['sites']
            if _s.get('core_radii_source') not in (None, 'untested'))
        # One implausible coordination condemns the structure, on the same
        # rule as the other screens.
        results['n_sites_cn_implausible'] = len(_cn_implausible)
        _judged = [_s for _s in results['sites']
                   if _s.get('cn_plausible') is not None]
        results['cn_plausible'] = (None if not _judged
                                   else not bool(_cn_implausible))
        if _cn_implausible:
            _w = min(_cn_implausible, key=lambda x: x.get('cn') or 99)
            if _w.get('cn_shannon_min') is None:
                print(f"\n  NO COORDINATION SHELL: {_w.get('element')} at "
                      f"{_w.get('site_label')} has no neighbours within the "
                      f"search radius. No bond valence sum is possible and "
                      f"none should be inferred.")
            else:
                print(f"\n  IMPLAUSIBLE COORDINATION: {_w.get('element')} at "
                      f"{_w.get('site_label')} has CN {_w.get('cn')}, outside the "
                      f"{_w.get('cn_shannon_min')}-{_w.get('cn_shannon_max')} range "
                      f"Shannon tabulates for it.")
                print(f"  Its bonds are of ordinary length, so no short-contact "
                      f"screen can see this; what is wrong is that bonds are "
                      f"MISSING. Treat the bond valence sum as incomplete.")
        results['core_shortest_contact_ratio'] = (round(_worst_ratio, 4)
                                                  if _worst_ratio is not None else None)
        # v2.0.3: one failing site condemns the structure, on the same rule as
        # every other screen. Comparing the worst ratio against the fixed
        # constant is the fault fixed for the bond-valence screen below; with a
        # per-site threshold it becomes wrong rather than merely redundant.
        results['core_geometry_plausible'] = (None if _worst_ratio is None
                                              else not _core_any_fail)
        results['core_contact_threshold'] = (
            _worst.get('core_contact_threshold') if _worst else None)
        results['bvs_distance_ratio'] = (round(_worst_bratio, 4)
                                         if _worst_bratio is not None else None)
        # One failing site condemns the structure, on the same rule as every
        # other screen. This previously compared the single worst RATIO against
        # the fixed constant, so the per-site thresholds were computed, exported
        # and then ignored by the only column anything downstream reads.
        results['bvs_geometry_plausible'] = (
            None if _worst_bratio is None else not _bvs_any_fail)
        results['bvs_distance_threshold'] = (
            _worst_b.get('bvs_distance_threshold') if _worst_b else None)

        if (results['bvs_geometry_plausible'] is False
                and results['core_geometry_plausible'] is not False):
            print(f"\n  SHORT CONTACT (bond valence test): {_worst_b.get('element')} at "
                  f"{_worst_b.get('site_label')} sits at {_worst_bratio:.0%} of the "
                  f"distance its own bond valence parameters imply.")
            print(f"  The radii-based screen did not catch this. Check the "
                  f"coordinates before trusting the result.")
        if results['core_geometry_plausible'] is False:
            print(f"\n  IMPLAUSIBLE GEOMETRY: {_worst.get('element')} at "
                  f"{_worst.get('site_label')} has a shortest contact of "
                  f"{_worst.get('min_bond_length') or _worst.get('avg_bond_length'):.3f} A, "
                  f"{_worst_ratio:.0%} of the "
                  f"{_worst.get('core_expected_contact') or float('nan'):.2f} A "
                  f"expected from ionic radii "
                  f"({_worst.get('core_radii_source')}).")
            print(f"  Treat every bond valence result for this structure as "
                  f"unreliable: it is a problem with the deposited coordinates, "
                  f"not with the chemistry.")

        # Half-lattice shift consistency. Runs after the geometry screens
        # because it uses core_expected_contact to reject a proposal that
        # would move a cation into an impossible contact.
        results['n_sites_shift_proposed'] = half_lattice_screen(
            file_path, results['sites'])

        # A1.1: anion-centred BVS, for the parameter-offset diagnosis
        # v2.0.2: anti-site exchange. Computed inside check_minority_species
        # to decline to expunge it, and then discarded; it is the fact that
        # decides which instability index to quote for this structure.
        results['n_antisite_species'], results['antisite_detail'] = antisite_exchange(
            per_atom_valences or {}, site_occupancies_data or {})
        results['has_antisite_disorder'] = bool(results['n_antisite_species'])
        if results['has_antisite_disorder']:
            print(f"\n  ANTI-SITE EXCHANGE: {results['antisite_detail']}.")
            print(f"  A minority species is being asked what its bond valence sum "
                  f"would be in a site the majority sizes, and the per-species GII "
                  f"weights that answer equally with the majority it sits among.")
            print(f"  Quote wagii or gii_site_averaged for this structure, not gii.")

        results['anion_sites'], results['anion_summary'] = anion_bvs_for_structure(
            file_path, results['sites'], cation_gii=results.get('gii'))
        results['success'] = True

    except Exception as e:
        results['error'] = f"Processing error: {str(e)}"
        import traceback
        print(f"  Detailed error: {traceback.format_exc()}")

    return results

