# collect_unique_elements_from_cifs removed at v2.0.13: superseded by
# prompt_for_oxidation_states, which collects the elements it needs
# from the parsed structures rather than by re-reading the CIFs.
def recommended_index(result):
    """(name, value) of the instability index to quote for this structure.

    v2.0.25. ONE definition, computed here where the site list is, rather
    than inferred downstream from a tier.

    The rule is about SHARED POSITIONS, not about detected antisite disorder.
    gii is a per-species index: where two species sit on one position it asks
    the minority what its bond valence would be in a site the majority sizes,
    and reports the answer as if it were a property of the structure.
    gii_site_averaged combines the sums at a shared position before taking the
    deviation, which is the question worth asking there.

    Measured on the 1881 spinels, 2.0.23 run:

        ACCEPT (no shared site)   gii 0.162   gii_site_averaged 0.165
        shared, antisite found    gii 0.707   gii_site_averaged 0.158
        shared, no antisite       gii 0.549   gii_site_averaged 0.213

    The previous rule named 'wagii' only where has_antisite_disorder was true
    and 'gii' otherwise, so 879 of the 1180 shared-site spinels were pointed
    at an index inflated by the sharing. Both groups land on the ACCEPT
    distribution under gii_site_averaged, so both get it.
    """
    _pos = {}
    for _s in (result.get('sites') or []):
        _pos.setdefault(str(_s.get('coords')), set()).add(_s.get('element'))
    _shared = any(len(_e) >= 2 for _e in _pos.values())
    for _name in (('gii_site_averaged',) if _shared else ()) + \
                 (('wagii',) if result.get('has_antisite_disorder') else ()) + \
                 ('gii',):
        _v = result.get(_name)
        if _v is not None and _v == _v:
            return _name, round(float(_v), 4)
    return 'gii', None


def _eir_prepare(cif_file, override_oxidation_states, fallback_oxidation_states):
    """Everything about ONE CIF that needs no other CIF.

    v2.0.27. Lifted verbatim out of the batch loop so it can run in a worker
    process. Nothing here reads or writes state shared with another file:

      _SIGN_INVERSIONS      cleared per structure since 2.0.27
      _MIXED_SIGN_ELEMENTS  set per structure since 2.0.46
      _USER_VALENCES        set per structure since 2.0.46
      _EIR_READ_FAILURES    returned as a delta and merged by the parent
      _NORMALISER_CACHE     a pure cache; a per-worker copy costs a little
      _ORIGIN_CHOICE_CACHE  repeated work and changes nothing

    Everything it prints is CAPTURED and returned rather than written to
    stdout. In a worker process stdout does not reach the notebook in any
    useful order, and in the parent it was already being collected for
    process_single_cif alone - the calls around it printed straight into the
    feed, between the reporter's blocks, which 2.0.18 was supposed to have
    ended. Capturing all of it makes serial and parallel produce the same
    feed, and puts the last few stray lines where the rest already went.

    Exceptions are deliberately NOT caught. A structure that kills the batch
    in serial must kill it in parallel too; making one of them survivable
    would be a change of behaviour smuggled in with a change of speed.
    """
    _mark = read_failure_mark()
    reset_sign_inversions()
    with _capture_stdout() as _buf:
        this_formula = formula_from_cif(cif_file)
        per_atom_valences = extract_per_atom_valences(str(cif_file))
        has_per_atom_explicit = any(
            v['explicit_valence'] is not None
            for v in per_atom_valences.values())
        ox_states, source, type7_result = get_oxidation_states_for_analysis(
            str(cif_file), this_formula, override_oxidation_states)
        if has_per_atom_explicit and type7_result:
            if type7_result.get('error_code') == 'TYPE7_EXPLICIT_MIXED_VALENCE':
                type7_result['has_type7_error'] = False
                type7_result['error_code'] = None
                type7_result['quality'] = 'per_atom_explicit'
        if (ox_states is None and not has_per_atom_explicit
                and fallback_oxidation_states):
            ox_states = fallback_oxidation_states
            source = 'fallback'
        if source is None and has_per_atom_explicit:
            source = 'per_atom_explicit'
        result = process_single_cif(str(cif_file), ox_states)
        error_flags = None
        if result.get('success'):
            error_flags = flag_all_error_types(
                str(cif_file), this_formula, result['sites'])
    return {'formula': this_formula,
            'has_per_atom_explicit': has_per_atom_explicit,
            'ox_states': ox_states, 'source': source,
            'type7_result': type7_result, 'result': result,
            'error_flags': error_flags, 'captured': _buf.getvalue(),
            'read_failures': take_read_failures(_mark)}


def _prepare_all(cif_files, override_oxidation_states,
                 fallback_oxidation_states, announce=None):
    """One payload per file, in order. v2.0.28: a wrapper over _measured_map,
    which is where the calibrate-then-decide logic lives now. This function
    kept a second copy of it until 2.0.27, and CELL 11 would have made a
    third."""
    import functools as _ft
    _fn = _ft.partial(_eir_prepare,
                      override_oxidation_states=override_oxidation_states,
                      fallback_oxidation_states=fallback_oxidation_states)
    return _measured_map(cif_files, _fn, announce=announce,
                         weight=lambda p: os.path.getsize(str(p)))


def prompt_for_oxidation_states(elements):
    """
    Interactive prompt for oxidation state assignment.
    Shows smart defaults based on oxide chemistry, allows user override.

    Args:
        elements: set of element symbols

    Returns:
        dict mapping element → oxidation state {e.g., 'Ti': 4, 'Na': 1}
    """
    # Smart defaults for oxide battery materials AND halides/sulfides
    OXIDE_DEFAULTS = {
        # Alkali metals
        'Li': 1, 'Na': 1, 'K': 1, 'Rb': 1, 'Cs': 1,
        # Alkaline earth
        'Mg': 2, 'Ca': 2, 'Sr': 2, 'Ba': 2,
        # Transition metals (oxide battery cathodes)
        'Ti': 4,   # Ti⁴⁺ most common in oxides
        'V': 5,    # V⁵⁺ in V₂O₅
        'Cr': 3,   # Cr³⁺ in chromites
        'Mn': 4,   # Mn⁴⁺ in MnO₂, battery cathodes (can also be 2, 3)
        'Fe': 3,   # Fe³⁺ slightly more common (can also be 2)
        'Co': 3,   # Co³⁺ in LiCoO₂
        'Ni': 2,   # Ni²⁺ in most cathodes
        'Cu': 2,   # Cu²⁺ most common
        'Zn': 2,   # Zn²⁺ only
        'Cd': 2,   # Cd²⁺ only
        # Other common
        'Al': 3, 'Sb': 5, 'Sn': 4, 'Zr': 4, 'Nb': 5, 'Mo': 6, 'W': 6,
        # Anions (oxides, halides, chalcogenides)
        'O': -2, 'F': -1, 'Cl': -1, 'Br': -1, 'I': -1,
        'S': -2, 'Se': -2, 'Te': -2,
        'N': -3, 'P': -3, 'As': -3, 'H': -1,
    }

    print("\n" + "="*80)
    print("OXIDATION STATE ASSIGNMENT")
    print("="*80)
    print("Please confirm oxidation states for elements found in your CIF files.")
    print("Defaults are shown in [brackets] - press ENTER to accept, or type new value.")
    print("="*80 + "\n")

    oxidation_states = {}

    # Sort: anions last, then alphabetical
    anions = sorted([e for e in elements if e in ['O', 'F', 'S', 'Cl', 'Br', 'I']])
    cations = sorted([e for e in elements if e not in anions])
    sorted_elements = cations + anions

    for element in sorted_elements:
        # Get default suggestion
        default = OXIDE_DEFAULTS.get(element)

        if default is not None:
            prompt_text = f"  {element:>2s} oxidation state [{default:+d}]: "
        else:
            # Check database
            common_states = db_manager.get_common_oxidation_states(element)
            if common_states:
                # For elements with multiple common states, show options
                states_str = ', '.join([f"{s:+d}" for s in common_states])
                default = common_states[0]  # Suggest first
                prompt_text = f"  {element:>2s} oxidation state (common: {states_str}) [{default:+d}]: "
            else:
                prompt_text = f"  {element:>2s} oxidation state [?]: "
                default = None

        while True:
            try:
                user_input = input(prompt_text).strip()

                if user_input == '' and default is not None:
                    # Accept default
                    oxidation_states[element] = default
                    break
                elif user_input != '':
                    # Parse user input
                    valence = int(user_input)
                    oxidation_states[element] = valence
                    break
                else:
                    # No default and no input
                    print("    ERROR: Please enter an oxidation state")

            except ValueError:
                print("    ERROR: Please enter a valid integer (e.g., 4, -2)")

    # Show summary
    print("\n" + "="*80)
    print("OXIDATION STATES CONFIRMED:")
    print("="*80)
    for element in sorted_elements:
        valence = oxidation_states[element]
        print(f"  {element:>2s}: {valence:+g}")
    print("="*80 + "\n")

    # Final confirmation
    confirm = input("Proceed with these oxidation states? [Y/n]: ").strip().lower()
    if confirm and confirm not in ['y', 'yes', '']:
        print("\nAborted by user")
        return None

    return oxidation_states

def batch_process_directory(directory_path):
    """
    Process all CIF files in a directory using EXACT Skuld 1.5 logic.
    Includes interactive oxidation state checkpoint for user control.
    Automatically creates /outputs subfolder for results.

    NEW IN v1.4: Attempts CIF oxidation state extraction before interactive prompt

    Args:
        directory_path: Path to directory containing CIF files

    Returns:
        pandas DataFrame with results, or None if failed
    """
    # Create outputs subdirectory
    output_dir = os.path.join(directory_path, "outputs")
    os.makedirs(output_dir, exist_ok=True)
    # v2.0.18: ONE STAMP FOR THE RUN. The results CSV, the failed-files CSV
    # and the new log all carry it, so the files one run produces can be told
    # from the files the last one produced. It used to be taken after the
    # loop, which is fine until you want to name the log before it.
    _run_stamp = datetime.now().strftime("%Y%m%d_%H%M%S")

    cif_files = list(Path(directory_path).glob("*.cif"))

    if not cif_files:
        print(f"No CIF files found in {directory_path}")
        return None

    # v2.0.46: THE READING STAGE (CELL 3). Every file is read once, here, and
    # everything after reads what it produced: the file itself where nothing
    # needed changing, which is every ICSD entry, or a corrected copy in
    # outputs/as_read/, one per structure, where something did. A structure
    # that cannot be read at all is a failure with its reason, recorded with
    # the others below, rather than whatever the first parser to meet it said.
    cif_files, _read_failures = read_folder(
        cif_files, os.path.join(output_dir, AS_READ_DIR))

    # ============================================================================
    # STEP 1: Config file provides OVERRIDES (highest priority)
    # ============================================================================
    config_path = auto_detect_config_file(directory_path)
    override_oxidation_states = None

    if config_path:
        override_oxidation_states = load_oxidation_states_from_config(config_path=config_path)
        print(f"✓ Config file loaded - these will override CIF values")

    # ============================================================================
    # STEP 2: Scan all CIFs to see what we're dealing with
    # ============================================================================
    print(f"\nScanning {len(cif_files)} CIF files for oxidation states...")

    cif_ox_summary = {'explicit': 0, 'inferred': 0, 'ambiguous': 0, 'missing': 0, 'per_atom_explicit': 0}
    elements_needing_fallback = set()
    ambiguous_files = []
    missing_files = []
    per_atom_explicit_files = []  # NEW: Track well-resolved mixed-valence files

    for cif_file in cif_files:
        try:
            formula = formula_from_cif(cif_file)

            # First check for per-atom explicit valences
            per_atom_valences = extract_per_atom_valences(str(cif_file))
            has_per_atom_explicit = any(
                v['explicit_valence'] is not None
                for v in per_atom_valences.values()
            )

            # Check for mixed valence at element level
            element_valences = {}
            for label, data in per_atom_valences.items():
                elem = data['element']
                val = data['explicit_valence']
                if val is not None:
                    if elem not in element_valences:
                        element_valences[elem] = set()
                    element_valences[elem].add(val)

            has_mixed_valence = any(len(vals) > 1 for vals in element_valences.values())

            # Classify the file
            if has_per_atom_explicit and has_mixed_valence:
                # Mixed valence WITH per-atom resolution - this is GOOD data!
                quality = 'per_atom_explicit'
                cif_ox_summary['per_atom_explicit'] += 1
                per_atom_explicit_files.append(cif_file.name)
                # NO fallback needed - we have explicit valences per atom

            elif has_per_atom_explicit:
                # Single valence per element with explicit data
                quality = 'explicit'
                cif_ox_summary['explicit'] += 1

            else:
                # Fall back to original flag_oxidation_state_issues logic
                result = flag_oxidation_state_issues(str(cif_file), formula)
                quality = result.get('quality', 'missing')
                cif_ox_summary[quality] = cif_ox_summary.get(quality, 0) + 1

                if quality == 'ambiguous':
                    ambiguous_files.append(cif_file.name)
                    parsed = parse_chemical_formula(formula)
                    for elem in parsed.keys():
                        if not is_anion(elem):
                            elements_needing_fallback.add(elem)
                elif quality == 'missing':
                    missing_files.append(cif_file.name)
                    parsed = parse_chemical_formula(formula)
                    for elem in parsed.keys():
                        if not is_anion(elem):
                            elements_needing_fallback.add(elem)
        except Exception as e:
            cif_ox_summary['missing'] += 1
            missing_files.append(cif_file.name)

    # Print summary
    print(f"  Explicit oxidation states:    {cif_ox_summary['explicit']} files")
    print(f"  Per-atom explicit (mixed):    {cif_ox_summary['per_atom_explicit']} files")  # NEW
    print(f"  Inferred oxidation states:    {cif_ox_summary['inferred']} files")
    print(f"  Ambiguous (needs fallback):   {cif_ox_summary['ambiguous']} files")
    print(f"  Missing oxidation states:     {cif_ox_summary['missing']} files")

    # NEW: Report per-atom explicit files (these are GOOD, not problematic)
    if per_atom_explicit_files:
        print(f"\n  ✓ Per-atom explicit files (mixed valence resolved):")
        for fn in per_atom_explicit_files[:10]:
            print(f"    - {fn}")
        if len(per_atom_explicit_files) > 10:
            print(f"    ... and {len(per_atom_explicit_files) - 10} more")

    # List problematic files (only truly ambiguous/missing)
    if ambiguous_files:
        print(f"\n  ⚠ Ambiguous files (will use fallback):")
        for fn in ambiguous_files[:20]:
            print(f"    - {fn}")
        if len(ambiguous_files) > 20:
            print(f"    ... and {len(ambiguous_files) - 20} more")

    if missing_files:
        print(f"\n  ⚠ Missing oxidation state files (will use fallback):")
        for fn in missing_files[:20]:
            print(f"    - {fn}")
        if len(missing_files) > 20:
            print(f"    ... and {len(missing_files) - 20} more")

    # Export review CSV (only for truly problematic files)
    if ambiguous_files or missing_files or per_atom_explicit_files:
        review_path = os.path.join(output_dir, "oxidation_state_review.csv")
        with open(review_path, 'w') as f:
            f.write("filename,status,notes\n")
            for fn in per_atom_explicit_files:
                f.write(f"{fn},per_atom_explicit,Mixed valence resolved - no action needed\n")
            for fn in ambiguous_files:
                f.write(f"{fn},ambiguous,Needs fallback oxidation states\n")
            for fn in missing_files:
                f.write(f"{fn},missing,No oxidation states found\n")
        print(f"\n  Review list exported to: {review_path}")

    # ============================================================================
    # STEP 3: Prompt for FALLBACK values only if needed
    # ============================================================================
    fallback_oxidation_states = {}

    if elements_needing_fallback and override_oxidation_states is None:
        print(f"\n{len(elements_needing_fallback)} elements need fallback oxidation states:")
        print(f"  {', '.join(sorted(elements_needing_fallback))}")
        print(f"\nThese will be used ONLY when CIF values are ambiguous/missing.")

        fallback_oxidation_states = prompt_for_oxidation_states(elements_needing_fallback)

    # ============================================================================
    # STEP 4: Process each file with per-file oxidation state resolution
    # ============================================================================
    all_results = []
    failed_files = []
    failed_file = None

    # v2.0.18: one narrator for the whole run. See BatchReporter in CELL 1b
    # for what was wrong with printing from thirty places instead.
    _rep = BatchReporter(
        directory_path, len(cif_files) + len(_read_failures), EIR_VERSION,
        log_path=os.path.join(output_dir, f'eir_batch_log_{_run_stamp}.txt'))
    _rep.open()

    # v2.0.27: the per-file work now happens in _eir_prepare, which may run
    # here or in a worker process. This loop keeps everything that must stay
    # in one place: the reporter, the row whitelist and the registers.
    def _announce(_tf, _est, _bias, _w, _why):
        _parallel_banner(_rep._emit, 'calibration', _tf, _est, _bias, _w, _why)

    _prepared = (_prepare_all(cif_files, override_oxidation_states,
                              fallback_oxidation_states, announce=_announce)
                 if cif_files else [])      # v2.0.46: none may be readable

    for _prog_i, (cif_file, _pre) in enumerate(zip(cif_files, _prepared), 1):
        merge_read_failures(_pre['read_failures'])
        this_formula = _pre['formula']

        has_per_atom_explicit = _pre['has_per_atom_explicit']
        ox_states = _pre['ox_states']
        source = _pre['source']
        type7_result = _pre['type7_result']

        # v2.0.19: NAME THE PER-ATOM CASE.
        #
        # get_oxidation_states_for_analysis resolves per ELEMENT, so a file
        # that states its valences per ATOM - the mixed-valence case, and the
        # best provenance a CIF can have - comes back with source=None and was
        # reported as '[no ox]'. The pre-scan in this same function already
        # counts those files correctly, under 'Per-atom explicit (mixed)', so
        # the batch knew and the feed did not.
        #
        # On the perovskite set that mislabelled ICSD 207498 and ICSD 33482 -
        # and 33482 is the worst structure in the run, GII 5.5634 on a 1.749 A
        # anion contact, which is the last entry whose provenance line should
        # be wrong.
        # v2.0.18: whatever this file printed is COLLECTED rather than left
        # to interleave with the next file's. Not discarded: it goes to the
        # run log always, and to the notebook as an indented block when
        # BATCH_DETAIL == 'full'. The header naming the file is printed by the
        # reporter below, before any of it.
        # v2.0.27: the capture now covers the oxidation-state resolution and
        # the error flags too, which used to print straight into the feed.
        result = _pre['result']
        _captured = _pre['captured']

        if result['success']:
            # v2.0.27: computed in _eir_prepare, beside the sites it reads.
            error_flags = _pre['error_flags']
            # v2.0.46: how the file was read, on every row (CELL 3)
            result['metadata'].update(reading_columns(cif_file.name))

            # v2.0.11: no structure tier here either. The demotions that used
            # to happen below - partial instability index, unscreened cation -
            # are the R facet of PGRM and are derived there from the same
            # evidence: a site with no bond valence sum is R1, a site with no
            # tabulated radius is R2. Computing them twice, in two places, with
            # two names, is how CELL 14 came to print two contradictory
            # recommendations on one page.
            structure_tier = None
            n_flagged = n_expunged = 0

            # v2.0.3 (rule 2). A site with no bond valence parameters never
            # reaches the instability index, and left no trace of having been
            # dropped. ICSD 93099 (LaPdO3) returned 0.0103, the second lowest
            # GII in the perovskite set, computed over its lanthanum alone.
            _dom = []
            for _s in result['sites']:
                if not _s.get('is_dominant_species', True):
                    continue
                _o = _s.get('occupancy')
                if _o is not None and float(_o) == 0.0:
                    continue
                _dom.append(_s)
            _uncovered = [_s for _s in _dom if _s.get('bvs') is None]
            result['gii_sites_total'] = len(_dom)
            result['gii_sites_covered'] = len(_dom) - len(_uncovered)
            result['gii_coverage_note'] = None
            if _uncovered:
                result['gii_coverage_note'] = '; '.join(
                    f"{_s.get('element')}({_s.get('valence')}) at "
                    f"{_s.get('site_label')}: no bond valence parameters"
                    for _s in _uncovered)
                # v2.0.18: now a note on this file's block, against
                # gii_sites_covered, which is the column it becomes.

            # The geometry side of the same rule. core_sites_untested has been
            # computed and exported since v1.8.8 and read by nothing; a site
            # with no Shannon radius is invisible to two of the five screens.
            # Five Fe(4+) sites in CaFeO3 and EuFeO3 sit here, all ACCEPT.
            # v2.0.18: likewise a note, against core_sites_untested.

            # Everything this structure has to say is known by here, so it can
            # be said in one block under a header that names the file.
            _rep.record(_prog_i, cif_file, result, source,
                        formula=this_formula, captured=_captured)

            # v2.0.25: once per structure, not once per site.
            _rec_name, _rec_val = recommended_index(result)

            for site in result['sites']:
                row = {
                    **result['metadata'],
                    **site,
                    'gii': round(result['gii'], 4) if result['gii'] is not None else None,
                    'wagii': round(result['wagii'], 4) if result.get('wagii') is not None else None,
                    'gii_sites_total': result.get('gii_sites_total'),
                    'gii_sites_covered': result.get('gii_sites_covered'),
                    'gii_coverage_note': result.get('gii_coverage_note'),
                    'n_sites_zero_occupancy': result.get('n_sites_zero_occupancy'),
                    # v2.0.16: these two are the audit trail for the 4.8
                    # change and in v2.0.15 neither reached the CSV, because
                    # this row is an explicit whitelist and they were not on
                    # it. A diagnostic that is computed, printed and not
                    # exported is the same fault as cation_packing_plausible
                    # in v2.0.12: the triage said one thing and the batch log
                    # said another.
                    'n_sites_below_floor': result.get('n_sites_below_floor'),
                    'gii_with_floor_failures': (
                        round(result['gii_with_floor_failures'], 4)
                        if result.get('gii_with_floor_failures') is not None
                        else None),
                    'bvs_discrepancy': round(result['bvs_discrepancy'], 4) if result.get('bvs_discrepancy') is not None else None,
                    'bvs_discrepancy_weighted': (
                        round(result['bvs_discrepancy_weighted'], 4)
                        if result.get('bvs_discrepancy_weighted') is not None
                        else None),
                    'gii_bondstr_old': (round(result['gii_bondstr_old'], 4)
                                        if result.get('gii_bondstr_old') is not None else None),
                    'gii_bondstr_a': (round(result['gii_bondstr_a'], 4)
                                      if result.get('gii_bondstr_a') is not None else None),
                    'gii_bondstr_b': (round(result['gii_bondstr_b'], 4)
                                      if result.get('gii_bondstr_b') is not None else None),
                    'gii_bondstr_c': (round(result['gii_bondstr_c'], 4)
                                      if result.get('gii_bondstr_c') is not None else None),
                    'gii_bondstr_convention': result.get('gii_bondstr_convention'),
                    'gii_bondstr_mult_source': result.get('gii_bondstr_mult_source'),
                    'gii_bondstr_n_no_mult': result.get('gii_bondstr_n_no_mult'),
                    'gii_site_averaged': (round(result['gii_site_averaged'], 4)
                                          if result.get('gii_site_averaged') is not None else None),
                    'n_crystallographic_sites': result.get('n_crystallographic_sites'),
                    'cif_sign_inversion': result.get('cif_sign_inversion'),
                    'cif_sign_inversion_detail': result.get('cif_sign_inversion_detail'),
                    'anion_anion_min': result.get('anion_anion_min'),
                    'polyanion_edge_min': result.get('polyanion_edge_min'),  # v2.0.46
                    'alternative_contacts_set_aside': result.get(
                        'alternative_contacts_set_aside'),                   # v2.0.46
                    'cation_cation_min': result.get('cation_cation_min'),
                    'cation_cation_contact': result.get(
                        'cation_cation_contact'),                            # v2.0.46
                    'cation_contact_partly_occupied': result.get(
                        'cation_contact_partly_occupied'),                   # v2.0.46
                    'anion_packing_plausible': result.get('anion_packing_plausible'),
        # v2.0.13a: computed and printed since v2.0.12 and never
        # exported, so the triage and summary both reported it as 0
        # structures flagged while the batch log said otherwise.
        'cation_packing_plausible': result.get('cation_packing_plausible'),
                    'structure_bvs_distance_ratio': result.get('bvs_distance_ratio'),
                    'structure_bvs_geometry_plausible': result.get('bvs_geometry_plausible'),
                    # v2.0.2: the structure-level radii-ratio verdict was
                    # computed but never exported, so the core_geometry_plausible
                    # column held the PER-SITE value while the two above were per
                    # structure. Anything reading all three the same way was
                    # wrong: groupby('filename').first() misses the failure
                    # whenever the bad site is not the first row.
                    'structure_core_geometry_plausible': result.get('core_geometry_plausible'),
                    'structure_core_shortest_contact_ratio': result.get('core_shortest_contact_ratio'),
                    'core_sites_tested': result.get('core_sites_tested'),
                    'core_sites_untested': result.get('core_sites_untested'),
                    'structure_cn_plausible': result.get('cn_plausible'),
                    'n_sites_cn_implausible': result.get('n_sites_cn_implausible'),
                    'n_sites_shift_proposed': result.get('n_sites_shift_proposed'),
                    'has_antisite_disorder': result.get('has_antisite_disorder'),
                    'n_antisite_species': result.get('n_antisite_species'),
                    'antisite_detail': result.get('antisite_detail'),
                    # Which instability index to quote for THIS structure.
                    # gii is per species and is misleading wherever a site is
                    # shared; see antisite_exchange() in CELL 1.
                    # v2.0.25: see recommended_index(). The old rule named
                    # 'wagii' only where antisite disorder was DETECTED and
                    # 'gii' otherwise, which pointed 879 of the 1180
                    # shared-site spinels at the index the sharing inflates.
                    'gii_recommended': _rec_name,
                    # And the value, because CELL 20 has been asking for
                    # gii_recommended_value since it was written -
                    # per.get('gii_recommended_value', per.get('gii')) - so
                    # every figure has silently plotted gii while its own code
                    # said it was plotting the recommended index.
                    'gii_recommended_value': _rec_val,
                    # Type 7 flags (oxidation state issues)
                    'flag_type7': type7_result.get('has_type7_error') if type7_result else None,
                    'type7_error_code': type7_result.get('error_code') if type7_result else None,
                    'oxidation_quality': type7_result.get('quality') if type7_result else None,
                    # NEW v1.4.2: Track where valence came from
                    'valence_source': site.get('valence_source', 'unknown'),
                    # NEW v1.4.2: Types 2-6 flags
                    'flag_type2': error_flags.get('flag_type2'),
                    'flag_type3': error_flags.get('flag_type3'),
                    'flag_type4': error_flags.get('flag_type4'),
                    'flag_type5': error_flags.get('flag_type5'),
                    'flag_type6': error_flags.get('flag_type6'),
                    'flag_type8': error_flags.get('flag_type8'),
                    'error_types_detected': error_flags.get('error_types_detected'),
                    'error_type_details': error_flags.get('error_type_details'),
                    # NEW v1.7: Structure-level integrity tier
                    'structure_tier': structure_tier,
                    'n_sites_flagged': n_flagged,
                    'n_sites_expunged': n_expunged,
                    # A1.1: anion-centred BVS summary
                    **(result.get('anion_summary') or {}),
                }
                all_results.append(row)

        else:
            _rep.failure(_prog_i, cif_file, result['error'])
            failed_files.append({
                'filename': cif_file.name,
                'error': result['error'],
                **reading_columns(cif_file.name),      # v2.0.46
            })

    # v2.0.46: the structures the reading stage could not read at all
    for _k, _f in enumerate(_read_failures, len(cif_files) + 1):
        _rep.failure(_k, _f['filename'], _f['error'])
        failed_files.append(_f)

    # ============================================================================
    # STEP 5: Save results to CSV files
    # ============================================================================
    if all_results:
        df = pd.DataFrame(all_results)

        # NEW IN v1.4: Ensure Type 7 columns exist
        type7_columns = ['flag_type7', 'type7_error_code', 'oxidation_quality']
        for col in type7_columns:
            if col not in df.columns:
                df[col] = None

        # ============================================================================
        # DATASET-LEVEL PASS: Flag multiple entries from same source paper (v1.7.2)
        # ============================================================================
        if 'icsd_code' in df.columns and 'authors' in df.columns:
            df = flag_same_source_entries(df)

            # Print summary of multi-entry sources
            multi = df[df['flag_multi_entry_source'] == True]
            if len(multi) > 0:
                multi_groups = multi.groupby('source_group').first().reset_index()
                print(f"\n⚠ Dataset-level check: {len(multi_groups)} source papers have multiple ICSD entries:")
                for _, grp in multi_groups.iterrows():
                    codes = grp['source_group_codes']
                    n = grp['source_group_size']
                    # Get one example formula per code
                    code_list = codes.split(',')
                    examples = []
                    for code in code_list[:4]:
                        formula = df[df['icsd_code'] == code]['chemical_formula'].iloc[0] if len(df[df['icsd_code'] == code]) > 0 else '?'
                        examples.append(f"{code}({formula})")
                    suffix = f" +{len(code_list)-4} more" if len(code_list) > 4 else ""
                    print(f"  {grp['source_group']}: {n} entries — {', '.join(examples)}{suffix}")
                print(f"  Note: multiple entries from one paper may represent different samples,")
                print(f"  refinement methods, or phase-separated components. Check the original")
                print(f"  paper to assess whether entries are independent determinations.")

        # Save results
        timestamp = _run_stamp      # v2.0.18: set once, before the loop
        results_file = os.path.join(output_dir,
                                    f"eir_batch_results_v{EIR_VERSION}_{timestamp}.csv")
        df.to_csv(results_file, index=False)

        # v2.0.34: say what this run produced, so nothing downstream has to
        # infer it from a directory listing. Written AFTER the CSV it names,
        # so a stem is only ever recorded once it exists. Plain text, one key
        # per line, because the point is to be readable at a glance.
        _stem = results_file[:-4] if results_file.endswith('.csv') else results_file
        _latest = os.path.join(output_dir, 'latest.txt')
        try:
            _n_struct_out = (int(df['filename'].nunique())
                             if 'filename' in df.columns else len(df))
            with open(_latest, 'w', encoding='utf-8') as _lf:
                _lf.write(f'version   {EIR_VERSION}\n')
                _lf.write(f'stamp     {timestamp}\n')
                _lf.write(f'stem      {_stem}\n')
                _lf.write(f'structures {_n_struct_out}\n')
            print(f"  latest.txt -> {os.path.basename(_stem)}")
        except OSError as _e:
            # A pointer that cannot be written is not a reason to lose a run
            # that has already been computed and saved.
            print(f"  ! could not write latest.txt: {type(_e).__name__}: {_e}")

        print(f"\n✓ Results saved to: {results_file}")
        print(f"  Total sites analysed: {len(df)}")
        print(f"  Total columns: {len(df.columns)}")

        # ============================================================================
        # PRINT STRUCTURE-TYPE ANALYSIS SUMMARY (Eir v1.4+)
        # ============================================================================
        if 'spinel_classification' in df.columns:
            spinel_count = df['spinel_classification'].notna().sum()
            if spinel_count > 0:
                spinel_structures = df[df['spinel_classification'].notna()]['filename'].nunique()
                print(f"\n  Spinel structures detected: {spinel_structures} files, {spinel_count} sites")
                print(f"    Classifications:")
                for classification in df['spinel_classification'].dropna().unique():
                    count = (df['spinel_classification'] == classification).sum()
                    print(f"      - {classification}: {count} sites")

                if 'inversion_parameter' in df.columns:
                    lambda_values = df['inversion_parameter'].dropna()
                    if len(lambda_values) > 0:
                        print(f"    Inversion parameters:")
                        print(f"      - λ = 0 (normal): {(lambda_values == 0.0).sum()} sites")
                        print(f"      - λ = 1 (inverse): {(lambda_values == 1.0).sum()} sites")
                        print(f"      - 0 < λ < 1 (random): {((lambda_values > 0.0) & (lambda_values < 1.0)).sum()} sites")

        # Build merged oxidation states dict for logging
        # Priority: override (config) > fallback (interactive prompt) > empty
        effective_oxidation_states = {}
        if fallback_oxidation_states:
            effective_oxidation_states.update(fallback_oxidation_states)
        if override_oxidation_states:
            effective_oxidation_states.update(override_oxidation_states)

        # Save oxidation states used for this batch
        oxidation_states_file = os.path.join(output_dir, f"oxidation_states_used_{timestamp}.json")
        with open(oxidation_states_file, 'w') as f:
            import json
            json.dump(effective_oxidation_states, f, indent=2, sort_keys=True)
        print(f"\n✓ Oxidation states saved to: {oxidation_states_file}")

        # Save failed files log if any
        if failed_files:
            failed_df = pd.DataFrame(failed_files)
            # v2.0.13: the version was hard-coded at v1.7, so a 2.0.x run
            # wrote its failures under a 1.7 filename and the two could not
            # be told apart in a directory holding both.
            failed_file = os.path.join(
                output_dir,
                f"eir_batch_failed_v{EIR_VERSION}_{timestamp}.csv")
            failed_df.to_csv(failed_file, index=False)
            print(f"✓ Failed files log saved to: {failed_file}")
            print(f"  ({len(failed_files)} files failed)")

        # Print summary statistics
        print(f"\n{'='*80}")
        print(f"EIR BATCH PROCESSOR v{EIR_VERSION} - Summary Statistics")
        print(f"{'='*80}")

        # Show oxidation states used
        print(f"\nOxidation states used:")
        for element in sorted(effective_oxidation_states.keys()):
            valence = effective_oxidation_states[element]
            print(f"  {element:>2s}: {valence:+g}")

        # Show GII statistics if available
        if 'gii' in df.columns and df['gii'].notna().any():
            print(f"\nGlobal Instability Index (GII) statistics:")
            gii_by_structure = df.groupby('filename')['gii'].first()
            print(f"  Mean GII: {gii_by_structure.mean():.4f}")
            print(f"  Min GII:  {gii_by_structure.min():.4f} ({gii_by_structure.idxmin()})")
            print(f"  Max GII:  {gii_by_structure.max():.4f} ({gii_by_structure.idxmax()})")

            stable_structures = (gii_by_structure < 0.1).sum()
            unstable_structures = (gii_by_structure >= 0.2).sum()
            print(f"  Stable (GII < 0.1): {stable_structures} structures")
            print(f"  Unstable (GII ≥ 0.2): {unstable_structures} structures")

        # The v1.7 ACCEPT/FLAG/EXPUNGE summary was removed at v2.0.13a. The
        # tier it counted was derived FROM the bond valence sum and was
        # retired at v2.0.11; the counters survived it and printed three
        # zeros at the end of every run. The verdict now comes from the PGRM
        # gates, reported by the post-processing cell and the triage.
        print(f"{'='*80}\n")

        # v2.0.18: the reconciliation goes last, because it is what you read
        # when a run ends - files in, rows out, how long, and which column
        # every note raised belongs to.
        _rep.close(n_rows=len(df), written=[results_file],
                   failed_path=failed_file)
        return df
    else:
        # v2.0.46: the failures are written even when nothing succeeded. A
        # folder of templates, or of files none of which can be read, used to
        # leave no record of why beyond the log.
        if failed_files:
            failed_file = os.path.join(
                output_dir, f"eir_batch_failed_v{EIR_VERSION}_{_run_stamp}.csv")
            pd.DataFrame(failed_files).to_csv(failed_file, index=False)
        _rep.close(n_rows=0, written=[], failed_path=failed_file)
        print("\n✗ No successful analyses")
        if failed_files:
            print(f"All {len(failed_files)} files failed. Check error messages above.")
        return None

# ============================================================================
# CONVENIENCE FUNCTIONS
# ============================================================================

def run_batch_analysis():
    """
    Convenience function for easy use in Jupyter notebooks or scripts.
    Opens directory selection dialog and processes all CIF files.

    Usage:
        from Eir_v1_1 import run_batch_analysis
        df = run_batch_analysis()

    Returns:
        pandas DataFrame with results, or None if failed/cancelled
    """
    print("\n" + "="*80)
    print("Running Eir v1.8.1 Batch Analysis...")
    print("="*80)

    # Select directory with tkinter dialog
    directory = select_directory()

    if directory is None:
        return None

    # Process all CIF files
    results_df = batch_process_directory(directory)

    if results_df is not None:
        print("\n" + "="*80)
        print("BATCH PROCESSING COMPLETE")
        print("="*80)
        print(f"Successfully analysed: {results_df['filename'].nunique()} structures")
        print(f"Total sites analysed: {len(results_df)}")
        output_dir = os.path.join(directory, "outputs")
        print(f"\nAll results saved to: {output_dir}")
        print("\nNext steps:")
        print("  1. Review the results CSV file")
        print("  2. Check for any failed files in the failed log")
        print("  3. Analyse results with statistical tools or custom scripts")

        return results_df

    return None

# ============================================================================
# SELF-CHECK (NEW IN v2.0.2)
# ============================================================================
# A cell that stops half way is the worst failure mode in a notebook: the
# names defined above the stop survive, the ones below do not, and the error
# appears later somewhere unrelated. This check runs last, so reaching it at
# all proves the cell completed, and it verifies that the cells this one
# depends on have been run too.

def _eir_self_check(verbose=True):
    """Confirm this cell completed and its dependencies are present."""
    exports = [
        'clean_cif_for_gemmi', 'calculate_bonds_from_positions',
        'parse_cif_file', 'extract_initial_site_data', 'auto_select_bond_types',
        'auto_analyze_coordination', 'auto_assign_valences',
        'perform_calculations_and_report', 'calculate_global_instability_index',
        'process_single_cif', 'batch_process_directory', 'run_batch_analysis',
        'guarded_shell_cn', 'full_shell_cn', 'group_bond_counts',
        'cn_fault', 'econ_bound', 'VALIDATE_CN', 'db_manager',
    ]
    # Names this cell uses but does not define. CELL 1 supplies most;
    # anion_bvs_for_structure comes from the anion-BVS cell and is needed only
    # at run time, so it is reported separately rather than as a hard failure.
    from_cell1 = [
        'EIR_VERSION', 'ANION_ANION_MIN', 'ANION_FORMERS', 'SHANNON_CN6_VIZ',
        'IMPLAUSIBLE_CONTACT_FRACTION', 'IMPLAUSIBLE_BVS_DISTANCE_FRACTION',
        'JT_OCTAHEDRAL_ELEMENTS', 'MAX_JT_AXIAL_RATIO', '_ANION_SET',
        '_EIR_GEOMETRY', '_SIGN_INVERSIONS', '_dbg', 'ge',
        'assess_site_geometry', 'anion_anion_contacts', 'classify_bond_pair',
        'analyze_mixed_occupancy_at_site', 'calculate_discrepancy_factor',
        'assign_confidence_flag', 'whatif_analysis',
        'check_minority_species', 'check_mixed_tm_site', 'flag_all_error_types',
        'flag_same_source_entries', 'flag_oxidation_state_issues',
        'extract_icsd_metadata', 'extract_per_atom_valences',
        'extract_site_occupancies', 'extract_cif_oxidation_states',
        'get_oxidation_states_for_analysis', 'parse_chemical_formula',
        'parse_atom_type_with_valence', 'is_anion', 'auto_detect_config_file',
        'load_oxidation_states_from_config', 'visualize_problematic_site_3d',
    ]
    g = globals()
    missing_here = [n for n in exports if n not in g]
    missing_dep = [n for n in from_cell1 if n not in g]
    deferred = [n for n in ['anion_bvs_for_structure'] if n not in g]

    if missing_here:
        raise NameError(
            f"This cell did not finish: {len(missing_here)} of its own names "
            f"are undefined ({', '.join(missing_here[:4])}...). Scroll up for "
            f"the real error and re-run this cell in full.")
    if missing_dep:
        raise NameError(
            f"{len(missing_dep)} names this cell needs are missing: "
            f"{', '.join(missing_dep[:6])}"
            f"{'...' if len(missing_dep) > 6 else ''}. These live in the "
            f"helper cell above (CELL 1 and the geometry core). Run that cell, "
            f"then this one.")
    if verbose:
        print('Eir 2.0.2 main cell loaded and self-checked.')
        print(f'  {len(exports)} exports defined, {len(from_cell1)} dependencies present.')
        if deferred:
            print(f"  note: {', '.join(deferred)} comes from the anion-BVS cell "
                  f"below; run it before batch processing.")
        print('  Coordination shell guard active: the gap-analysis CN is checked')
        print('  against ECoN before the bond valence sum is computed, and the sum')
        print('  is reported over both the chosen and the full distance shell.')
        print('  Run VALIDATE_CN() to check the guard, then Cell 8 to batch process.')
    return True


_eir_self_check()